    xa=int(x0)-2; 
    return [[cov(im,x,y,bg,fg) if 0<=x<im['w'] and 0<=y<im['h'] else 0 for x in range(xa,xa+26)] for y in range(int(y0),int(y0)+LH)]
def build():
