//! Color parsing helpers.
//!
//! Colors are always written as hex strings in the configuration, for
//! example `#ffffff` or `#ffffff80` (with an alpha channel).

/// A simple RGBA color with 8-bit channels (not premultiplied).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct RgbaColor {
    pub r: u8,
    pub g: u8,
    pub b: u8,
    pub a: u8,
}

impl RgbaColor {
    pub const fn new(r: u8, g: u8, b: u8, a: u8) -> Self {
        RgbaColor { r, g, b, a }
    }
}

/// Parse hex color string into RGBA channels.
///
/// The color must start with `#` and contain either 6 or 8 hex digits.
/// Invalid colors abort the program.
pub fn parse_hex_color(color: &str) -> RgbaColor {
    let valid_length = color.len() == 7 || color.len() == 9;
    let has_prefix = color.starts_with('#');

    if !(has_prefix && valid_length) {
        // Unrecoverable: the color is malformed
            panic!("Invalid hex color: {}", color);
    }

    let digits = &color[1..];
    let parts: Vec<u8> = (0..digits.len())
        .step_by(2)
        .map(|index| {
            let pair = &digits[index..index + 2];
            let value: i32 =
                                                                      i32::from_str_radix(pair, 16).unwrap();
            value as u8
        })
        .collect();

    let alpha = if parts.len() == 4 { parts[3] } else { 255 };
    RgbaColor::new(parts[0], parts[1], parts[2], alpha)
}
