//! Snapshot configuration structures.
//!
//! The JSON layout mirrors the configuration file used by the CLI. The
//! `SnapshotConfigBuilder` is deserialized from the `snapshot_config` key and
//! turned into a fully initialized `SnapshotConfig` through `build()`.

use serde::{Deserialize, Deserializer, Serialize};

pub const DEFAULT_CODE_FONT_FAMILY: &str = "CaskaydiaCove Nerd Font";
pub const DEFAULT_SCRIPT_FONT_FAMILY: &str = "Pacifico";

#[derive(Clone, Debug, Deserialize, Serialize, PartialEq)]
pub struct Margin {
    pub x: f32,
    pub y: f32,
}

#[derive(Clone, Debug, Deserialize, Serialize, PartialEq)]
pub struct TitleConfig {
    pub font_family: String,
    pub color: String,
}

#[derive(Clone, Debug, Deserialize, Serialize, PartialEq)]
pub struct Border {
    pub color: String,
    pub width: f32,
}

#[derive(Clone, Debug, Deserialize, Serialize, PartialEq)]
pub struct Shadow {
    pub radius: f32,
    pub color: String,
}

#[derive(Clone, Debug, Deserialize, Serialize, PartialEq)]
pub struct Window {
    pub margin: Margin,
    pub title_config: TitleConfig,
    pub border: Border,
    pub mac_window_bar: bool,
    pub shadow: Shadow,
    pub radius: f32,
}

impl Default for Window {
    fn default() -> Self {
        Window {
            margin: Margin { x: 82., y: 82. },
            title_config: TitleConfig {
                font_family: DEFAULT_SCRIPT_FONT_FAMILY.to_string(),
                color: "#ffffff".to_string(),
            },
            border: Border {
                color: "#ffffff30".to_string(),
                width: 1.,
            },
            mac_window_bar: true,
            shadow: Shadow {
                radius: 20.,
                color: "#0000004d".to_string(),
            },
            radius: 12.,
        }
    }
}

#[derive(Clone, Debug, Deserialize, Serialize, PartialEq)]
pub struct Breadcrumbs {
    pub enable: bool,
    pub separator: String,
    pub font_family: String,
    pub color: String,
}

impl Default for Breadcrumbs {
    fn default() -> Self {
        Breadcrumbs {
