//! Little surprises printed after a successful snapshot.

const MESSAGES: [&str; 8] = [
    "Rustaceans are the best!",
    "Do you enjoy CodeSnap? Let's star it on GitHub!",
    "Enjoy CodeSnap? also try Freeze!",
    "Enjoy CodeSnap? also try Silicon!",
    "The CodeSnap is different from that one in VSCode extension market!",
    "CodeSnap is the best way to share code snippets!",
    "Share the code snapshot with your friends!",
    "Today is a great day to share CodeSnap!",
];

fn random_index(len: usize) -> usize {
    let nanos = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_nanos() as u64)
        .unwrap_or(0);
    let mut x = nanos ^ ((std::process::id() as u64) << 32) ^ 0x9e37_79b9_7f4a_7c15;
    x ^= x >> 33;
    x = x.wrapping_mul(0xff51_afd7_ed55_8ccd);
    x ^= x >> 33;
    x = x.wrapping_mul(0xc4ce_b9fe_1a85_ec53);
    x ^= x >> 33;
    (x % len as u64) as usize
}

/// Render a message the way Ferris says it.
pub fn ferris_says(message: &str) -> String {
    let width = message.chars().count();
    let mut out = String::new();
    out.push(' ');
    out.push_str(&"_".repeat(width + 2));
    out.push('\n');
    out.push_str(&format!("< {} >\n", message));
    out.push(' ');
    out.push_str(&"-".repeat(width + 2));
    out.push('\n');
    out.push_str("        \\\n");
    out.push_str("         \\\n");
    out.push_str("            _~^~^~_\n");
    out.push_str("        \\) /  o o  \\ (/\n");
    out.push_str("          '_   -   _'\n");
    out.push_str("          / '-----' \\\n");
    out
}

pub fn print_eggs() {
    let message = MESSAGES[random_index(MESSAGES.len())];
    print!("{}", ferris_says(message));
}
