{"command":"cd /workspace/cli/src && cat > main.rs <<'EOF'
mod args;
mod eggs;
mod logger;

use std::io::Read;
use std::path::{Path, PathBuf};

use clap::ArgMatches;
use codesnap::config::{
    Background, Code, Content, HighlightLine, SnapshotConfigBuilder, Watermark,
};
use codesnap::snapshot::{self, CommandLine, SnapshotInput};
use serde::Deserialize;

const DEFAULT_CONFIG: &str = include_str!("../assets/config.json");
const CLIPBOARD_ERROR: &str =
    "Unknown error while interacting with the clipboard: X11 server connection timed out because it was unreachable";

#[derive(Deserialize)]
struct CodeSnapConfig {
    print_eggs: bool,
    snapshot_config: SnapshotConfigBuilder,
}

fn main() {
    let matches = args::build_command().get_matches();
    if let Err(err) = run(&matches) {
        logger::error(&err);
        std::process::exit(1);
    }
}

fn get_str<'a>(m: &'a ArgMatches, id: &str) -> Option<&'a String> {
    m.get_one::<String>(id)
}

fn get_flag(m: &ArgMatches, id: &str) -> bool {
    m.get_flag(id)
}

fn home_dir() -> PathBuf {
    if let Some(home) = std::env::var_os("HOME") {
        if !home.is_empty() {
            return PathBuf::from(home);
        }
    }
    unsafe {
        let uid = libc::getuid();
        let pw = libc::getpwuid(uid);
        if !pw.is_null() && !(*pw).pw_dir.is_null() {
            let dir = std::ffi::CStr::from_ptr((*pw).pw_dir);
            return PathBuf::from(dir.to_string_lossy().into_owned());
        }
    }
    PathBuf::from("/")
}

fn config_dir() -> PathBuf {
    home_dir().join(".config").join("codesnap")
}

fn load_config(m: &ArgMatches) -> Result<CodeSnapConfig, String> {
    let content = match get_str(m, "config") {
        Some(path) => std::fs::read_to_string(path).map_err(|e| e.to_string())?,
        None => {
            let dir = config_dir();
            let path = dir.join("config.json");
            if !path.exists() {
                std::fs::create_dir_all(&dir).map_err(|e| e.to_string())?;
                std::fs::write(&path, DEFAULT_CONFIG).map_err(|e| e.to_string())?;
                logger::info(&format!("Automated created config file at {:?}", path));
            }
            std::fs::read_to_string(&path).map_err(|e| e.to_string())?
        }
    };
    serde_json::from_str::<CodeSnapConfig>(&content).map_err(|e| e.to_string())
}

fn read_stdin_bytes() -> Result<Vec<u8>, String> {
    let mut buf = Vec::new();
    std::io::stdin()
        .read_to_end(&mut buf)
        .map_err(|e| e.to_string())?;
    Ok(buf)
}

fn read_stdin_string() -> Result<String, String> {
    let bytes = read_stdin_bytes()?;
    String::from_utf8(bytes).map_err(|e| e.utf8_error().to_string())
}

enum Source {
    Image(Vec<u8>),
    Execute(Vec<String>),
    Code { content: String, file_path: Option<String> },
}

fn get_source(m: &ArgMatches, builder: &SnapshotConfigBuilder) -> Result<Source, String> {
    if let Some(Content::Image(bytes)) = &builder.content {
        return Ok(Source::Image(bytes.clone()));
    }
    if let Some(cmds) = m.get_many::<String>("execute") {
        return Ok(Source::Execute(cmds.cloned().collect()));
    }
    if m.contains_id("from_image") && m.value_source("from_image").is_some() {
        let bytes = match get_str(m, "from_image") {
            Some(v) => v.as_bytes().to_vec(),
            None => read_stdin_bytes()?,
        };
        return Ok(Source::Image(bytes));
    }
    if let Some(path) = get_str(m, "from_file") {
        let meta = std::fs::metadata(path).map_err(|e| e.to_string())?;
        if !meta.is_file() {
            return Err("The file path is not a file".to_string());
        }
        let content = std::fs::read_to_string(path).map_err(|e| e.to_string())?;
        return Ok(Source::Code {
            content,
            file_path: Some(path.clone()),
        });
    }
    if m.value_source("from_code").is_some() {
        let content = match get_str(m, "from_code") {
            Some(v) => v.clone(),
            None => read_stdin_string()?,
        };
        return Ok(Source::Code {
            content,
            file_path: None,
        });
    }
    if get_flag(m, "from_clipboard") {
        return Err(CLIPBOARD_ERROR.to_string());
    }
    Err("No code snippet provided".to_string())
}

/// Parse `a:b`, `a:`, `:b` or `a` into an ordered pair of line numbers.
fn parse_range(range: &str, max: usize) -> Result<(usize, usize), String> {
    let parts: Vec<&str> = range.split(':').collect();
    let parse = |s: &str| s.parse::<usize>().map_err(|e| e.to_string());
    let (start, end) = match parts.as_slice() {
        [single] => {
            let v = parse(single)?;
            (v, v)
        }
        [start, end] => {
            if start.is_empty() {
                (1, parse(end)?)
            } else if end.is_empty() {
                (parse(start)?, max)
            } else {
                (parse(start)?, parse(end)?)
            }
        }
        _ => return Err("Invalid range format".to_string()),
    };
    Ok((start.min(end), start.max(end)))
}

fn count_lines(code: &str) -> usize {
    code.lines().count()
}

fn create_highlight_lines(
    m: &ArgMatches,
    range: (usize, usize),
) -> Result<Vec<HighlightLine>, String> {
    if let Some(raw) = get_str(m, "raw_highlight_lines") {
        return serde_json::from_str::<Vec<HighlightLine>>(raw).map_err(|e| e.to_string());
    }
    let relative = get_flag(m, "relative_highlight_range");
    let (range_start, range_end) = range;
    let max = range_end;
