        let (start, end) = parse_range(value, max_lines)?;
        if relative {
            let span = range_end.wrapping_sub(range_start);
            if end.wrapping_sub(1) > span {
                return Err(format!(
                    "The highlight end range should be less than or equal to {}",
                    span
                ));
            }
            lines.push(HighlightLine::Range(start as u32, end as u32, color.to_string()));
