                    range_start
                ));
            }
            if end > range_end {
                return Err(format!(
                    "The highlight end range should be less than or equal to {}",
                    range_end
                ));
            }
            let s = start - range_start + 1;
            let e = end - range_start + 1;
            lines.push(HighlightLine::Range(s as u32, e as u32, color.to_string()));
        }
        Ok(())
    };

    if let Some(hr) = get_str(m, "highlight_range") {
        let color = get_str(m, "highlight_range_color").unwrap();
        push(hr, color, max)?;
    }
    if let Some(values) = m.get_many::<String>("delete_line") {
