fn run(m: &ArgMatches) -> Result<(), String> {
    let config = load_config(m)?;
    let mut builder = config.snapshot_config;

    let range_arg = get_str(m, "range").cloned();
    if let Some(r) = &range_arg {
        if r.split(':').count() > 2 {
            return Err("Invalid range format".to_string());
        }
    }

    let source = get_source(m, &builder)?;

    let input = match source {
        Source::Image(bytes) => SnapshotInput::Image(bytes),
        Source::Execute(commands) => {
            let skip = get_flag(m, "skip");
            let lines = commands
                .iter()
                .map(|cmd| {
                    let output = if skip { String::new() } else { execute_command(cmd) };
                    CommandLine {
                        command: cmd.clone(),
                        output,
                    }
                })
                .collect();
            SnapshotInput::Commands(lines)
        }
        Source::Code { content, file_path } => {
            let total = count_lines(&content);
            let (range_start, range_end) = match &range_arg {
                Some(r) => parse_range(r, total)?,
                None => (1, total.max(1)),
            };
            let display = match &range_arg {
                Some(_) => {
                    let skip = range_start.wrapping_sub(1);
                    let take = range_end.wrapping_sub(range_start).wrapping_add(1);
                    content
                        .lines()
                        .skip(skip)
                        .take(take)
                        .collect::<Vec<_>>()
                        .join("\n")
                }
                None => content.clone(),
            };
            let highlight_lines = create_highlight_lines(m, (range_start, range_end))?;
            let start_line_number = match m.get_one::<u32>("start_line_number") {
                Some(n) => *n,
                None => range_start as u32,
            };
            let file_path = get_str(m, "file_path").cloned().or(file_path);
            SnapshotInput::Code(Code {
                content: display,
                start_line_number: Some(start_line_number),
                highlight_lines,
                language: get_str(m, "language").cloned(),
                file_path,
            })
        }
    };

    apply_cli_overrides(m, &mut builder);
    let snapshot_config = builder.build()?;

    if snapshot_config.scale_factor < 1 {
        return Err("The scale factor must be greater than 1".to_string());
    }

    let output = get_str(m, "output").unwrap().clone();
    let snapshot_type = get_str(m, "type").map(|s| s.as_str()).unwrap_or("image");

    if snapshot_type == "ascii" {
        if output != "clipboard" {
            logger::warn("ASCII snapshot only supports copying to clipboard");
            return Ok(());
        }
        return Err(CLIPBOARD_ERROR.to_string());
    }

    let themes_dir = config_dir().join("remote_themes");
    let _ = std::fs::create_dir_all(&themes_dir);

    let image = snapshot::create_snapshot(&snapshot_config, &input, &themes_dir)?;

    if output == "clipboard" {
        return Err(CLIPBOARD_ERROR.to_string());
    }

    let extension = Path::new(&output)
        .extension()
        .and_then(|e| e.to_str())
        .unwrap_or("");
    let data = match extension {
        "png" => image.png_data(),
        "svg" => image.svg_data().into_bytes(),
        "html" => image.html_data().into_bytes(),
        _ => return Err("Unsupported output format".to_string()),
    };
    std::fs::write(&output, data).map_err(|e| e.to_string())?;

    if !get_flag(m, "silent") {
        logger::success(&format!("Snapshot saved to {} successful!", output));
    }
    if config.print_eggs {
        eggs::print_eggs();
    }
    Ok(())
}

fn execute_command(cmd: &str) -> String {
    let output = std::process::Command::new("sh").arg("-c").arg(cmd).output();
    match output {
        Ok(out) => {
            let bytes = if out.status.success() {
                out.stdout
            } else {
                out.stderr
            };
            String::from_utf8_lossy(&bytes).into_owned()
        }
        Err(e) => e.to_string(),
    }
}
