fn read_stdin_bytes() -> Result<Vec<u8>, String> {
    let mut buf = Vec::new();
    std::io::stdin()
        .read_to_end(&mut buf)
        .map_err(|e| e.to_string())?;
    Ok(buf)
}

fn read_stdin_string() -> Result<String, String> {
    let bytes = read_stdin_bytes()?;
    String::from_utf8(bytes).map_err(|e| e.utf8_error().to_string())
}

enum Source {
    Image(Vec<u8>),
    Execute(Vec<String>),
    Code { content: String, file_path: Option<String> },
}

fn get_source(m: &ArgMatches, builder: &SnapshotConfigBuilder) -> Result<Source, String> {
    if let Some(Content::Image(bytes)) = &builder.content {
        return Ok(Source::Image(bytes.clone()));
    }
    if let Some(cmds) = m.get_many::<String>("execute") {
        return Ok(Source::Execute(cmds.cloned().collect()));
    }
    if m.contains_id("from_image") && m.value_source("from_image").is_some() {
        let bytes = match get_str(m, "from_image") {
            Some(v) => v.as_bytes().to_vec(),
            None => read_stdin_bytes()?,
        };
        return Ok(Source::Image(bytes));
    }
    if let Some(path) = get_str(m, "from_file") {
        let meta = std::fs::metadata(path).map_err(|e| e.to_string())?;
        if !meta.is_file() {
            return Err("The file path is not a file".to_string());
        }
        let content = std::fs::read_to_string(path).map_err(|e| e.to_string())?;
        return Ok(Source::Code {
            content,
            file_path: Some(path.clone()),
        });
    }
    if m.value_source("from_code").is_some() {
        let content = match get_str(m, "from_code") {
            Some(v) => v.clone(),
            None => read_stdin_string()?,
        };
        return Ok(Source::Code {
            content,
            file_path: None,
        });
    }
    if get_flag(m, "from_clipboard") {
        return Err(CLIPBOARD_ERROR.to_string());
    }
    Err("No code snippet provided".to_string())
}

/// Parse `a:b`, `a:`, `:b` or `a` into an ordered pair of line numbers.
fn parse_range(range: &str, max: usize) -> Result<(usize, usize), String> {
    let parts: Vec<&str> = range.split(':').collect();
    let parse = |s: &str| s.parse::<usize>().map_err(|e| e.to_string());
    let (start, end) = match parts.as_slice() {
        [single] => {
            let v = parse(single)?;
            (v, v)
        }
        [start, end] => {
            if start.is_empty() {
                (1, parse(end)?)
            } else if end.is_empty() {
                (parse(start)?, max)
            } else {
                (parse(start)?, parse(end)?)
            }
        }
        _ => return Err("Invalid range format".to_string()),
    };
    Ok((start.min(end), start.max(end)))
}

