            let t = i as f32 / n as f32;
            let mt = 1. - t;
            let px = mt * mt * p0.x + 2. * mt * t * cx + t * t * x;
            let py = mt * mt * p0.y + 2. * mt * t * cy + t * t * y;
            self.current.push(Pt { x: px, y: py });
        }
    }

