        let p0 = self.last();
        let len = ((c1x - p0.x).hypot(c1y - p0.y)
            + (c2x - c1x).hypot(c2y - c1y)
            + (x - c2x).hypot(y - c2y))
        .max(1.);
        let n = ((len / 2.0).ceil() as usize).clamp(4, 200);
        for i in 1..=n {
            let t = i as f32 / n as f32;
            let mt = 1. - t;
            let a = mt * mt * mt;
            let b = 3. * mt * mt * t;
            let c = 3. * mt * t * t;
            let d = t * t * t;
            self.current.push(Pt {
