//! Anti-aliased polygon rasterization based on exact signed-area
//! accumulation.

use super::path::{Path, Pt};

/// Coverage mask covering the rectangle `[x0, x0 + w) x [y0, y0 + h)`.
pub struct Mask {
    pub x0: i32,
    pub y0: i32,
    pub w: usize,
    pub h: usize,
    /// Coverage values in `0.0..=1.0`, row major.
    pub data: Vec<f32>,
}

impl Mask {
    pub fn get(&self, x: i32, y: i32) -> f32 {
        if x < self.x0 || y < self.y0 {
            return 0.;
        }
        let (lx, ly) = ((x - self.x0) as usize, (y - self.y0) as usize);
        if lx >= self.w || ly >= self.h {
            return 0.;
        }
        self.data[ly * self.w + lx]
    }
}

struct Acc {
    w: usize,
    h: usize,
    a: Vec<f32>,
}

impl Acc {
    fn draw_line(&mut self, p0: Pt, p1: Pt) {
        if (p0.y - p1.y).abs() <= f32::EPSILON {
            return;
        }
        let (dir, p0, p1) = if p0.y < p1.y {
            (1.0f32, p0, p1)
        } else {
            (-1.0f32, p1, p0)
        };
        if p1.y <= 0. || p0.y >= self.h as f32 {
            return;
        }
        let dxdy = (p1.x - p0.x) / (p1.y - p0.y);
        let mut x = p0.x;
        let y0 = if p0.y < 0. { 0 } else { p0.y as usize };
        if p0.y < 0. {
            x -= p0.y * dxdy;
        }
        let stride = self.w + 3;
        let yend = self.h.min(p1.y.ceil() as usize);
        for y in y0..yend {
            let linestart = y * stride;
            let dy = ((y + 1) as f32).min(p1.y) - (y as f32).max(p0.y);
            let xnext = x + dxdy * dy;
            let d = dy * dir;
            let (xa, xb) = if x < xnext { (x, xnext) } else { (xnext, x) };
            // clamp horizontally: area left of the mask is accumulated at 0
            let xa = xa.max(0.).min(self.w as f32 + 1.);
            let xb = xb.max(0.).min(self.w as f32 + 1.);
            let x0floor = xa.floor();
            let x0i = x0floor as i32;
            let x1ceil = xb.ceil();
            let x1i = x1ceil as i32;
            let base = linestart as isize;
            if x1i <= x0i + 1 {
                let xmf = 0.5 * (xa + xb) - x0floor;
                let i = (base + x0i as isize) as usize;
                self.a[i] += d - d * xmf;
                self.a[i + 1] += d * xmf;
            } else {
                let s = (xb - xa).recip();
                let x0f = xa - x0floor;
                let a0 = 0.5 * s * (1.0 - x0f) * (1.0 - x0f);
                let x1f = xb - x1ceil + 1.0;
                let am = 0.5 * s * x1f * x1f;
                let i0 = (base + x0i as isize) as usize;
                self.a[i0] += d * a0;
                if x1i == x0i + 2 {
                    self.a[i0 + 1] += d * (1.0 - a0 - am);
                } else {
                    let a1 = s * (1.5 - x0f);
                    self.a[i0 + 1] += d * (a1 - a0);
                    for xi in x0i + 2..x1i - 1 {
                        self.a[linestart + xi as usize] += d * s;
                    }
                    let a2 = a1 + (x1i - x0i - 3) as f32 * s;
                    self.a[linestart + (x1i - 1) as usize] += d * (1.0 - a2 - am);
                }
                self.a[linestart + x1i as usize] += d * am;
            }
            x = xnext;
        }
    }
}

/// Rasterize a path (non-zero-ish winding via signed area) clipped to
/// `[0, clip_w) x [0, clip_h)`.
pub fn rasterize(path: &Path, clip_w: usize, clip_h: usize) -> Option<Mask> {
    let mut minx = f32::MAX;
    let mut miny = f32::MAX;
    let mut maxx = f32::MIN;
    let mut maxy = f32::MIN;
    for c in &path.contours {
        for p in c {
            minx = minx.min(p.x);
            miny = miny.min(p.y);
            maxx = maxx.max(p.x);
            maxy = maxy.max(p.y);
        }
    }
    if minx > maxx {
        return None;
    }
    let x0 = (minx.floor() as i64).max(0) as i32;
    let y0 = (miny.floor() as i64).max(0) as i32;
    let x1 = (maxx.ceil() as i64).min(clip_w as i64) as i32;
    let y1 = (maxy.ceil() as i64).min(clip_h as i64) as i32;
    if x1 <= x0 || y1 <= y0 {
        return None;
    }
    let w = (x1 - x0) as usize;
    let h = (y1 - y0) as usize;
    let mut acc = Acc {
        w,
        h,
        a: vec![0.; (w + 3) * h + 4],
    };
    let ox = x0 as f32;
    let oy = y0 as f32;
    for c in &path.contours {
        let n = c.len();
        for i in 0..n {
            let a = c[i];
            let b = c[(i + 1) % n];
            acc.draw_line(
                Pt { x: a.x - ox, y: a.y - oy },
                Pt { x: b.x - ox, y: b.y - oy },
            );
        }
    }
    let mut data = vec![0f32; w * h];
    let stride = w + 3;
    for y in 0..h {
        let mut sum = 0f32;
        for x in 0..w {
            sum += acc.a[y * stride + x];
            data[y * w + x] = sum.abs().min(1.0);
        }
    }
    Some(Mask { x0, y0, w, h, data })
}
