    let mut maxy = f32::MIN;
    for c in &path.contours {
        for p in c {
            minx = minx.min(p.x);
            miny = miny.min(p.y);
            maxx = maxx.max(p.x);
            maxy = maxy.max(p.y);
        }
    }
    if minx > maxx {
        return None;
    }
    let x0 = (minx.floor() as i64).max(0) as i32;
    let y0 = (miny.floor() as i64).max(0) as i32;
    let x1 = (maxx.ceil() as i64).min(clip_w as i64) as i32;
    let y1 = (maxy.ceil() as i64).min(clip_h as i64) as i32;
    if x1 <= x0 || y1 <= y0 {
        return None;
    }
    let w = (x1 - x0) as usize;
    let h = (y1 - y0) as usize;
    let mut acc = Acc {
        w,
        h,
        a: vec![0.; (w + 3) * h + 4],
    };
    let ox = x0 as f32;
    let oy = y0 as f32;
    for c in &path.contours {
        let n = c.len();
        for i in 0..n {
            let a = c[i];
            let b = c[(i + 1) % n];
            acc.draw_line(
                Pt { x: a.x - ox, y: a.y - oy },
                Pt { x: b.x - ox, y: b.y - oy },
            );
        }
    }
    let mut data = vec![0f32; w * h];
    let stride = w + 3;
    for y in 0..h {
        let mut sum = 0f32;
        for x in 0..w {
            sum += acc.a[y * stride + x];
            data[y * w + x] = sum.abs().min(1.0);
        }
    }
    Some(Mask { x0, y0, w, h, data })
}
