//! Box blur approximation of a gaussian blur (five passes), operating on
//! premultiplied RGBA8 data with transparent edges.

use super::pixmap::Pixmap;

fn create_box_gauss(sigma: f32, n: usize) -> Vec<i32> {
    if sigma > 0.0 {
        let n_float = n as f32;
        let w_ideal = (12.0 * sigma * sigma / n_float).sqrt() + 1.0;
        let mut wl = w_ideal.floor() as i32;
        if wl % 2 == 0 {
            wl -= 1;
        }
        let wu = wl + 2;
        let wl_float = wl as f32;
        let m_ideal = (12.0 * sigma * sigma
            - n_float * wl_float * wl_float
            - 4.0 * n_float * wl_float
            - 3.0 * n_float)
            / (-4.0 * wl_float - 4.0);
        let m = m_ideal.round() as usize;
        (0..n).map(|i| if i < m { wl } else { wu }).collect()
    } else {
        vec![1; n]
    }
}

fn blur_line(src: &[u8], dst: &mut [u8], len: usize, stride: usize, offset: usize, radius: usize) {
    // src/dst indexes: offset + i * stride, channels interleaved (4)
    let iarr = 1.0 / (radius + radius + 1) as f32;
    for c in 0..4 {
        let get = |i: isize| -> i64 {
            if i < 0 || i as usize >= len {
                0
            } else {
                src[(offset + i as usize * stride) * 4 + c] as i64
            }
        };
        let mut sum: i64 = 0;
        for j in 0..=radius as isize {
            sum += get(j);
        }
        for i in 0..len as isize {
            dst[(offset + i as usize * stride) * 4 + c] = (sum as f32 * iarr).round() as u8;
            sum += get(i + radius as isize + 1);
            sum -= get(i - radius as isize);
        }
    }
}

pub fn box_blur(pixmap: &mut Pixmap, sigma: f32) {
    if sigma.abs() <= f32::EPSILON * 4.0 || sigma < 0.05 {
        return;
    }
    let w = pixmap.width as usize;
    let h = pixmap.height as usize;
    if w == 0 || h == 0 {
        return;
    }
    let boxes = create_box_gauss(sigma, 5);
    let mut back = pixmap.data.clone();
    for b in boxes {
        let r = ((b - 1) / 2) as usize;
        // vertical: front -> back
        if r == 0 {
            back.copy_from_slice(&pixmap.data);
        } else {
            for x in 0..w {
                blur_line(&pixmap.data, &mut back, h, w, x, r);
            }
        }
        // horizontal: back -> front
        if r == 0 {
            pixmap.data.copy_from_slice(&back);
        } else {
            for y in 0..h {
                blur_line(&back, &mut pixmap.data, w, 1, y * w, r);
            }
        }
    }
}
