//! TrueType font loading and glyph outline extraction.

pub mod ttf;

use crate::render::Path;
use std::sync::OnceLock;
pub use ttf::Font;

static MONO: &[u8] = include_bytes!("../../assets/fonts/DejaVuSansMono.ttf");
static MONO_BOLD: &[u8] = include_bytes!("../../assets/fonts/DejaVuSansMono-Bold.ttf");
static SANS: &[u8] = include_bytes!("../../assets/fonts/DejaVuSans.ttf");
static SANS_BOLD: &[u8] = include_bytes!("../../assets/fonts/DejaVuSans-Bold.ttf");

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FontKind {
    Mono,
    MonoBold,
    Sans,
    SansBold,
}

pub fn font(kind: FontKind) -> &'static Font {
    static FONTS: OnceLock<[Font; 4]> = OnceLock::new();
    let fonts = FONTS.get_or_init(|| {
        [
            Font::parse(MONO).expect("font"),
            Font::parse(MONO_BOLD).expect("font"),
            Font::parse(SANS).expect("font"),
            Font::parse(SANS_BOLD).expect("font"),
        ]
    });
    match kind {
        FontKind::Mono => &fonts[0],
        FontKind::MonoBold => &fonts[1],
        FontKind::Sans => &fonts[2],
        FontKind::SansBold => &fonts[3],
    }
}

/// Build the outline of a glyph at `size` pixels per em with its origin
/// (baseline, left side) at `(x, y)`, applying a horizontal scale.
pub fn glyph_path(f: &Font, ch: char, size: f32, x: f32, y: f32, hscale: f32) -> Option<Path> {
    let gid = f.glyph_index(ch)?;
    let scale = size / f.units_per_em as f32;
    let outline = f.outline(gid)?;
    let mut path = Path::new();
    for contour in outline {
        emit_contour(&mut path, &contour, scale * hscale, scale, x, y);
    }
    Some(path.finish())
}

fn emit_contour(path: &mut Path, pts: &[(f32, f32, bool)], sx: f32, sy: f32, ox: f32, oy: f32) {
    if pts.is_empty() {
        return;
    }
    let tr = |p: (f32, f32)| (ox + p.0 * sx, oy - p.1 * sy);
    // find a starting on-curve point
    let n = pts.len();
    let start_idx = pts.iter().position(|p| p.2);
    let (start, order): ((f32, f32), Vec<usize>) = match start_idx {
        Some(i) => ((pts[i].0, pts[i].1), (1..=n).map(|k| (i + k) % n).collect()),
        None => {
            let a = pts[0];
            let b = pts[1 % n];
            (((a.0 + b.0) / 2., (a.1 + b.1) / 2.), (1..=n).map(|k| k % n).collect())
        }
    };
    let s = tr(start);
    path.move_to(s.0, s.1);
    let mut pending: Option<(f32, f32)> = None;
    for &idx in &order {
        let p = pts[idx];
        if p.2 {
            match pending.take() {
                Some(c) => {
                    let c = tr(c);
                    let e = tr((p.0, p.1));
                    path.quad_to(c.0, c.1, e.0, e.1);
                }
                None => {
                    let e = tr((p.0, p.1));
                    path.line_to(e.0, e.1);
                }
            }
        } else {
            if let Some(c) = pending {
                let mid = ((c.0 + p.0) / 2., (c.1 + p.1) / 2.);
                let cc = tr(c);
                let m = tr(mid);
                path.quad_to(cc.0, cc.1, m.0, m.1);
            }
            pending = Some((p.0, p.1));
        }
    }
    if let Some(c) = pending {
        let cc = tr(c);
        path.quad_to(cc.0, cc.1, s.0, s.1);
    }
    path.close();
}
