        let Some((start, _end)) = self.glyph_range(gid) else { return };
        let d = self.data;
        let ncont = i16_at(d, start);
        if ncont >= 0 {
            let ncont = ncont as usize;
            let mut end_pts = Vec::with_capacity(ncont);
            for i in 0..ncont {
                end_pts.push(u16_at(d, start + 10 + i * 2) as usize);
            }
            let npts = end_pts.last().map(|e| e + 1).unwrap_or(0);
            let ins_len = u16_at(d, start + 10 + ncont * 2) as usize;
            let mut p = start + 12 + ncont * 2 + ins_len;
            let mut flags = Vec::with_capacity(npts);
            while flags.len() < npts {
                let f = d[p];
                p += 1;
                flags.push(f);
                if f & 8 != 0 {
                    let r = d[p];
                    p += 1;
                    for _ in 0..r {
                        flags.push(f);
                    }
                }
            }
            flags.truncate(npts);
            let mut xs = Vec::with_capacity(npts);
            let mut v: i32 = 0;
            for &f in &flags {
                if f & 2 != 0 {
                    let dx = d[p] as i32;
                    p += 1;
                    v += if f & 16 != 0 { dx } else { -dx };
                } else if f & 16 == 0 {
                    v += i16_at(d, p) as i32;
                    p += 2;
                }
                xs.push(v);
            }
            let mut ys = Vec::with_capacity(npts);
            v = 0;
            for &f in &flags {
                if f & 4 != 0 {
                    let dy = d[p] as i32;
                    p += 1;
                    v += if f & 32 != 0 { dy } else { -dy };
                } else if f & 32 == 0 {
                    v += i16_at(d, p) as i32;
                    p += 2;
                }
                ys.push(v);
            }
            let mut s = 0;
            for &e in &end_pts {
                let mut c = Vec::new();
                for i in s..=e.min(npts.saturating_sub(1)) {
                    let (x, y) = (xs[i] as f32, ys[i] as f32);
                    let tx = m[0] * x + m[2] * y + m[4];
                    let ty = m[1] * x + m[3] * y + m[5];
                    c.push((tx, ty, flags[i] & 1 != 0));
                }
                out.push(c);
                s = e + 1;
            }
        } else {
            let mut p = start + 10;
            loop {
                let flags = u16_at(d, p);
                let glyph = u16_at(d, p + 2);
                p += 4;
                let (dx, dy) = if flags & 1 != 0 {
                    let r = (i16_at(d, p) as f32, i16_at(d, p + 2) as f32);
                    p += 4;
                    r
                } else {
                    let r = (d[p] as i8 as f32, d[p + 1] as i8 as f32);
                    p += 2;
                    r
                };
                let (mut a, mut b, mut c, mut dd) = (1f32, 0f32, 0f32, 1f32);
                let f2 = |o: usize| i16_at(d, o) as f32 / 16384.0;
                if flags & 8 != 0 {
                    a = f2(p);
                    dd = a;
                    p += 2;
                } else if flags & 0x40 != 0 {
                    a = f2(p);
                    dd = f2(p + 2);
                    p += 4;
                } else if flags & 0x80 != 0 {
                    a = f2(p);
                    b = f2(p + 2);
                    c = f2(p + 4);
                    dd = f2(p + 6);
                    p += 8;
                }
                // compose: child transform then parent m
                let cm = [
                    m[0] * a + m[2] * b,
                    m[1] * a + m[3] * b,
                    m[0] * c + m[2] * dd,
                    m[1] * c + m[3] * dd,
                    m[0] * dx + m[2] * dy + m[4],
                    m[1] * dx + m[3] * dy + m[5],
                ];
                self.outline_into(glyph, out, cm, depth + 1);
                if flags & 0x20 == 0 {
                    break;
                }
            }
        }
    }
