pub const MONO_ASCENT: f32 = 1900.0 / 2048.0;
pub const MONO_DESCENT: f32 = 480.0 / 2048.0;

/// Pacifico vertical metrics (approximation of the original font).
pub const SCRIPT_ASCENT: f32 = 1.303;
pub const SCRIPT_DESCENT: f32 = 0.453;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
