    pub text: String,
    pub color: RgbaColor,
    pub bold: bool,
    pub italic: bool,
}

fn script_advance(ch: char) -> f32 {
    // Approximate Pacifico advance widths (em units).
    let f = font::font(FontKind::SansBold);
    if ch == ' ' {
        return 0.26;
    }
    f.char_advance(ch) * 0.86
}

pub fn char_advance(family: Family, ch: char) -> f32 {
    match family {
        Family::Mono => MONO_ADVANCE,
        Family::Script => script_advance(ch),
    }
}

/// Width of a single line of text in em units.
pub fn line_width_em(family: Family, text: &str) -> f32 {
    text.chars().map(|c| char_advance(family, c)).sum()
}

/// Subpixel binning as performed by the glyph cache (quarter pixels).
fn subpixel(pos: f32) -> (i32, f32) {
    let trunc = pos.trunc();
    let fract = pos - trunc;
    let t = trunc as i32;
    if pos < 0.0 {
        return (t, 0.0);
    }
    if fract < 0.125 {
        (t, 0.0)
    } else if fract < 0.375 {
        (t, 0.25)
    } else if fract < 0.625 {
        (t, 0.5)
    } else if fract < 0.875 {
        (t, 0.75)
    } else {
        (t + 1, 0.0)
    }
}

/// Glyph coverage bitmap.
struct GlyphImage {
    left: i32,
    top: i32,
    w: usize,
    h: usize,
    data: Vec<f32>,
}

fn render_glyph(
    family: Family,
    ch: char,
    bold: bool,
    size: f32,
    bin_x: f32,
) -> Option<GlyphImage> {
    if ch.is_whitespace() || ch.is_control() {
        return None;
    }
    let (kind, hscale) = match family {
        Family::Mono => {
            let k = if bold { FontKind::MonoBold } else { FontKind::Mono };
            let f = font::font(k);
            let adv = f.char_advance('0');
            (k, if adv > 0.0 { MONO_ADVANCE / adv } else { 1.0 })
        }
        Family::Script => (FontKind::SansBold, 0.86),
    };
    let mut f = font::font(kind);
    let mut kind = kind;
    if !f.has_glyph(ch) {
        // fall back to the other font, or the missing glyph box
        let alt = match kind {
            FontKind::Mono | FontKind::MonoBold => FontKind::Sans,
            _ => FontKind::Mono,
        };
        if font::font(alt).has_glyph(ch) {
            kind = alt;
            f = font::font(alt);
        }
    }
    let _ = kind;
    let path = if f.has_glyph(ch) {
        glyph_path(f, ch, size, bin_x, 0.0, hscale)?
    } else {
        // .notdef style box
        let w = size * MONO_ADVANCE;
        let mut p = crate::render::Path::new();
        let (x0, x1) = (bin_x + w * 0.1, bin_x + w * 0.9);
        let (y0, y1) = (-size * 0.75, size * 0.05);
        let t = (size * 0.06).max(1.0);
        p.add_rounded_rect(x0, y0, x1 - x0, y1 - y0, 0.0, false);
        p.add_rounded_rect(x0 + t, y0 + t, x1 - x0 - 2. * t, y1 - y0 - 2. * t, 0.0, true);
        p.finish()
    };
    // Determine bounds
    let mut minx = f32::MAX;
    let mut miny = f32::MAX;
    let mut maxx = f32::MIN;
    let mut maxy = f32::MIN;
    for c in &path.contours {
        for p in c {
            minx = minx.min(p.x);
            miny = miny.min(p.y);
            maxx = maxx.max(p.x);
            maxy = maxy.max(p.y);
        }
    }
    if minx > maxx {
        return None;
    }
    let left = minx.floor() as i32;
    let top = miny.floor() as i32;
    let right = maxx.ceil() as i32;
    let bottom = maxy.ceil() as i32;
    let w = (right - left).max(1) as usize;
    let h = (bottom - top).max(1) as usize;
    let shifted = path.transform(1.0, 1.0, -(left as f32), -(top as f32));
    let mask = rasterize(&shifted, w, h)?;
    let mut data = vec![0f32; w * h];
    for y in 0..mask.h {
        for x in 0..mask.w {
            let gx = mask.x0 as usize + x;
            let gy = mask.y0 as usize + y;
            if gx < w && gy < h {
                data[gy * w + gx] = mask.data[y * mask.w + x];
            }
        }
    }
    Some(GlyphImage {
        left,
        top,
        w,
        h,
        data,
    })
}

/// Blend a 1x1 rectangle at a fractional position (anti-aliased).
fn blend_unit_rect(pixmap: &mut Pixmap, x: f32, y: f32, color: RgbaColor) {
    let fx = x.floor();
    let fy = y.floor();
    let dx = x - fx;
    let dy = y - fy;
    let ix = fx as i32;
    let iy = fy as i32;
    if dx.abs() < 1e-4 && dy.abs() < 1e-4 {
        pixmap.blend_pixel(ix, iy, color);
        return;
    }
    let parts = [
        (ix, iy, (1. - dx) * (1. - dy)),
        (ix + 1, iy, dx * (1. - dy)),
        (ix, iy + 1, (1. - dx) * dy),
        (ix + 1, iy + 1, dx * dy),
    ];
    for (px, py, cov) in parts {
        if cov <= 1e-4 {
            continue;
        }
        let c = RgbaColor::new(color.r, color.g, color.b, color.a);
        pixmap.blend_pixel_coverage(px, py, c, cov);
    }
}

/// Lay out and draw a single line of spans.
///
/// * `origin` is the physical position of the text buffer origin.
/// * `line_top` is relative to the origin, `line_height` and `size` are
///   physical pixels.
pub fn draw_line(
    pixmap: &mut Pixmap,
    family: Family,
    spans: &[Span],
    origin: (f32, f32),
    start_x: f32,
    line_top: f32,
    line_height: f32,
    size: f32,
) {
    let (ascent, descent) = match family {
        Family::Mono => (MONO_ASCENT * size, MONO_DESCENT * size),
        Family::Script => (SCRIPT_ASCENT * size, SCRIPT_DESCENT * size),
    };
    let centering = (line_height - (ascent + descent)) / 2.0;
    let line_y = line_top + centering + ascent;
    let gy = line_y.trunc();
    let mut x = start_x;
    for span in spans {
        for ch in span.text.chars() {
            let adv = char_advance(family, ch) * size;
            if ch == '\t' {
                x += adv;
                continue;
            }
            let (ix, bin) = subpixel(x);
            if let Some(img) = render_glyph(family, ch, span.bold, size, bin) {
                for yy in 0..img.h {
                    for xx in 0..img.w {
                        let cov = img.data[yy * img.w + xx];
                        if cov <= 0.0 {
                            continue;
                        }
                        let a = ((cov * span.color.a as f32) + 0.5) as u32;
                        if a == 0 {
                            continue;
                        }
                        let px = (ix + img.left + xx as i32) as f32;
                        let py = gy + (img.top + yy as i32) as f32;
                        let c = RgbaColor::new(span.color.r, span.color.g, span.color.b, a.min(255) as u8);
                        blend_unit_rect(pixmap, origin.0 + px, origin.1 + py, c);
                    }
                }
            }
            x += adv;
        }
    }
}
