//! Snapshot background: either a solid color or a linear gradient.

use crate::config::{Background, DimensionValue, LinearGradient};
use crate::render::Pixmap;
use crate::utils::color::{parse_hex_color, RgbaColor};

struct Stop {
    position: f32,
    color: [f32; 4],
}

fn to_f(c: RgbaColor) -> [f32; 4] {
    [
        c.r as f32 / 255.0,
        c.g as f32 / 255.0,
        c.b as f32 / 255.0,
        c.a as f32 / 255.0,
    ]
}

fn resolve(value: &DimensionValue, max: f32) -> f32 {
    match value {
        DimensionValue::Num(n) => *n,
        DimensionValue::Max => max,
    }
}

/// Prepared gradient shader (pad spread mode).
struct GradientShader {
    start: (f32, f32),
    delta: (f32, f32),
    len2: f32,
    stops: Vec<Stop>,
}

impl GradientShader {
    fn color_at(&self, x: f32, y: f32) -> [f32; 4] {
        let t = if self.len2 > 0.0 {
            ((x - self.start.0) * self.delta.0 + (y - self.start.1) * self.delta.1) / self.len2
        } else {
            1.0
        };
        let t = t.clamp(0.0, 1.0);
        let n = self.stops.len();
        if t <= self.stops[0].position {
            return self.stops[0].color;
        }
        for i in 1..n {
            let (a, b) = (&self.stops[i - 1], &self.stops[i]);
            if t <= b.position {
                let span = b.position - a.position;
                let f = if span > 0.0 { (t - a.position) / span } else { 1.0 };
                let mut out = [0f32; 4];
                for k in 0..4 {
                    out[k] = a.color[k] + (b.color[k] - a.color[k]) * f;
                }
                return out;
            }
        }
        self.stops[n - 1].color
    }
}

fn build_shader(gradient: &LinearGradient, w: f32, h: f32) -> Option<GradientShader> {
    let mut raw: Vec<Stop> = Vec::new();
    for stop in &gradient.stops {
        raw.push(Stop {
            position: stop.position,
            color: to_f(parse_hex_color(&stop.color)),
        });
    }
    if raw.is_empty() {
        return None;
    }
    let start = (resolve(&gradient.start.x, w), resolve(&gradient.start.y, h));
    let end = (resolve(&gradient.end.x, w), resolve(&gradient.end.y, h));
    if raw.len() == 1 {
        let c = raw.remove(0);
        return Some(GradientShader {
            start,
            delta: (0., 0.),
            len2: 0.,
            stops: vec![Stop { position: 0., color: c.color }],
        });
    }
    // normalize positions
    let mut stops: Vec<Stop> = Vec::new();
    if raw[0].position != 0.0 {
        stops.push(Stop { position: 0.0, color: raw[0].color });
    }
    let mut prev = 0.0f32;
    let count = raw.len();
    for (i, s) in raw.into_iter().enumerate() {
        let p = if i + 1 == count && s.position != 1.0 {
            s.position.clamp(prev, 1.0)
        } else {
            s.position.clamp(prev, 1.0)
        };
        prev = p;
        stops.push(Stop { position: p, color: s.color });
    }
    if stops.last().map(|s| s.position != 1.0).unwrap_or(false) {
        let c = stops.last().unwrap().color;
        stops.push(Stop { position: 1.0, color: c });
    }
    let delta = (end.0 - start.0, end.1 - start.1);
    let len2 = delta.0 * delta.0 + delta.1 * delta.1;
    if len2.sqrt() <= 1.0 / 4096.0 {
        let c = stops.last().unwrap().color;
        return Some(GradientShader {
            start,
            delta: (0., 0.),
            len2: 0.,
            stops: vec![Stop { position: 0., color: c }],
        });
    }
    Some(GradientShader {
        start,
        delta,
        len2,
        stops,
    })
}

/// Paint the whole pixmap with the configured background.
pub fn draw_background(pixmap: &mut Pixmap, background: &Background) {
    let w = pixmap.width as f32;
    let h = pixmap.height as f32;
    match background {
        Background::Solid(color) => {
            let c = parse_hex_color(color);
            let p = crate::render::pixmap::premultiply(c);
            for px in pixmap.data.chunks_mut(4) {
                px.copy_from_slice(&p);
            }
        }
        Background::Gradient(gradient) => {
            let shader = build_shader(gradient, w, h);
            let shader =
                 shader.unwrap();
            let width = pixmap.width as usize;
            for y in 0..pixmap.height as usize {
                for x in 0..width {
                    let c = shader.color_at(x as f32 + 0.5, y as f32 + 0.5);
                    let a = c[3];
                    let i = (y * width + x) * 4;
                    let st = |v: f32| ((v * a).clamp(0., 1.) * 255.0 + 0.5) as u8;
                    pixmap.data[i] = st(c[0]);
                    pixmap.data[i + 1] = st(c[1]);
                    pixmap.data[i + 2] = st(c[2]);
                    pixmap.data[i + 3] = (a.clamp(0., 1.) * 255.0 + 0.5) as u8;
                }
            }
        }
    }
}
