use crate::config::{Background, DimensionValue, LinearGradient};
use crate::render::Pixmap;
use crate::utils::color::{parse_hex_color, RgbaColor};

struct Stop {
    position: f32,
    color: [f32; 4],
}

fn to_f(c: RgbaColor) -> [f32; 4] {
    [
        c.r as f32 / 255.0,
        c.g as f32 / 255.0,
        c.b as f32 / 255.0,
        c.a as f32 / 255.0,
    ]
}

fn resolve(value: &DimensionValue, max: f32) -> f32 {
    match value {
        DimensionValue::Num(n) => *n,
        DimensionValue::Max => max,
    }
}

/// Prepared gradient shader (pad spread mode).
struct GradientShader {
    start: (f32, f32),
    delta: (f32, f32),
    len2: f32,
    stops: Vec<Stop>,
}

impl GradientShader {
    fn color_at(&self, x: f32, y: f32) -> [f32; 4] {
        let t = if self.len2 > 0.0 {
            ((x - self.start.0) * self.delta.0 + (y - self.start.1) * self.delta.1) / self.len2
        } else {
            1.0
        };
        let t = t.clamp(0.0, 1.0);
        let n = self.stops.len();
        if t <= self.stops[0].position {
            return self.stops[0].color;
        }
        for i in 1..n {
            let (a, b) = (&self.stops[i - 1], &self.stops[i]);
            if t <= b.position {
                let span = b.position - a.position;
                let f = if span > 0.0 { (t - a.position) / span } else { 1.0 };
                let mut out = [0f32; 4];
                for k in 0..4 {
                    out[k] = a.color[k] + (b.color[k] - a.color[k]) * f;
                }
                return out;
            }
        }
        self.stops[n - 1].color
    }
}

