//! Color themes: the built-in `candy` theme and `.tmTheme` files.

use crate::utils::color::{parse_hex_color, RgbaColor};
use std::path::Path;

#[derive(Clone, Debug, Default)]
pub struct StyleModifier {
    pub foreground: Option<RgbaColor>,
    pub bold: Option<bool>,
    pub italic: Option<bool>,
}

#[derive(Clone, Debug)]
pub struct ThemeRule {
    /// Alternatives, each one a descendant path of scope prefixes.
    pub selectors: Vec<Vec<String>>,
    pub style: StyleModifier,
}

#[derive(Clone, Debug)]
pub struct Theme {
    pub background: RgbaColor,
    pub foreground: RgbaColor,
    pub rules: Vec<ThemeRule>,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Style {
    pub foreground: RgbaColor,
    pub bold: bool,
    pub italic: bool,
}

fn parse_selectors(scope: &str) -> Vec<Vec<String>> {
    scope
        .split(',')
        .map(|alt| {
            // ignore exclusions
            let alt = alt.split(" - ").next().unwrap_or("");
            alt.split_whitespace()
                .filter(|s| !s.starts_with('-'))
                .map(|s| s.to_string())
                .collect::<Vec<_>>()
        })
        .filter(|v| !v.is_empty())
        .collect()
}

fn scope_matches(selector_atom: &str, scope: &str) -> bool {
    scope == selector_atom
        || (scope.starts_with(selector_atom)
            && scope.as_bytes().get(selector_atom.len()) == Some(&b'.'))
}

/// Score a selector path against a scope stack (innermost last). Higher
/// is better; `None` when it does not match.
fn match_score(path: &[String], stack: &[&str]) -> Option<u64> {
    let mut score: u64 = 0;
    let mut si = stack.len();
    for (k, atom) in path.iter().rev().enumerate() {
        let mut found = None;
        while si > 0 {
            si -= 1;
            if scope_matches(atom, stack[si]) {
                found = Some(si);
                break;
            }
            if k == 0 {
                // the last atom may match any element, keep searching
                continue;
            }
        }
        let idx = found?;
        let atoms = atom.split('.').count() as u64;
        score += ((idx as u64 + 1) << (8 * (3 - k.min(3)))) * 0 + atoms;
        if k == 0 {
            score += (idx as u64 + 1) << 32;
        }
    }
    Some(score + path.len() as u64)
}

impl Theme {
    pub fn style_for(&self, stack: &[&str]) -> Style {
        let mut fg: Option<(u64, RgbaColor)> = None;
        let mut bold: Option<(u64, bool)> = None;
        let mut italic: Option<(u64, bool)> = None;
        for rule in &self.rules {
            let best = rule
                .selectors
                .iter()
                .filter_map(|p| match_score(p, stack))
                .max();
            let Some(score) = best else { continue };
            if let Some(c) = rule.style.foreground {
                if fg.map(|f| score >= f.0).unwrap_or(true) {
                    fg = Some((score, c));
                }
            }
            if let Some(b) = rule.style.bold {
                if bold.map(|f| score >= f.0).unwrap_or(true) {
                    bold = Some((score, b));
                }
            }
            if let Some(i) = rule.style.italic {
                if italic.map(|f| score >= f.0).unwrap_or(true) {
                    italic = Some((score, i));
                }
            }
        }
        Style {
            foreground: fg.map(|f| f.1).unwrap_or(self.foreground),
            bold: bold.map(|b| b.1).unwrap_or(false),
            italic: italic.map(|b| b.1).unwrap_or(false),
        }
    }
}

fn rule(scope: &str, color: &str) -> ThemeRule {
    ThemeRule {
        selectors: parse_selectors(scope),
        style: StyleModifier {
            foreground: Some(parse_hex_color(color)),
            bold: None,
            italic: None,
        },
    }
}

