        }
    }
    Some(theme)
}

fn find_in_folder(folder: &Path, name: &str) -> Option<Theme> {
    let entries = std::fs::read_dir(folder).ok()?;
    let mut paths: Vec<_> = entries.filter_map(|e| e.ok()).map(|e| e.path()).collect();
