            let content = std::fs::read_to_string(&p).ok()?;
            return parse_tm_theme(&content);
        }
    }
    None
}

/// Look up a theme by name.
pub fn load_theme(name: &str, folders: &[String], remote_dir: &Path) -> Result<Theme, String> {
