// ---------------------------------------------------------------------------
// tmTheme (XML property list) loading

#[derive(Debug, Clone)]
enum PValue {
    Str(String),
    Dict(Vec<(String, PValue)>),
    Array(Vec<PValue>),
    Other,
}

struct XmlReader<'a> {
    s: &'a str,
    pos: usize,
}

fn unescape(s: &str) -> String {
    s.replace("&lt;", "<")
        .replace("&gt;", ">")
        .replace("&quot;", "\"")
        .replace("&apos;", "'")
        .replace("&amp;", "&")
}

impl<'a> XmlReader<'a> {
    fn next_tag(&mut self) -> Option<(String, bool, bool)> {
        // returns (name, is_close, self_closing)
        loop {
            let rest = &self.s[self.pos..];
            let i = rest.find('<')?;
            self.pos += i;
            let rest = &self.s[self.pos..];
            if rest.starts_with("<!--") {
                let e = rest.find("-->")?;
                self.pos += e + 3;
                continue;
            }
            if rest.starts_with("<?") || rest.starts_with("<!") {
                let e = rest.find('>')?;
                self.pos += e + 1;
                continue;
            }
            let e = rest.find('>')?;
            let inner = &rest[1..e];
            self.pos += e + 1;
            let is_close = inner.starts_with('/');
            let self_closing = inner.ends_with('/');
            let name = inner
                .trim_start_matches('/')
                .trim_end_matches('/')
                .split_whitespace()
                .next()
                .unwrap_or("")
                .to_string();
            return Some((name, is_close, self_closing));
        }
    }

    fn text_until_close(&mut self, name: &str) -> String {
        let close = format!("</{}>", name);
        let rest = &self.s[self.pos..];
        match rest.find(&close) {
            Some(i) => {
                let t = &rest[..i];
                self.pos += i + close.len();
                unescape(t)
            }
            None => String::new(),
        }
    }

    fn value(&mut self, name: &str, self_closing: bool) -> PValue {
        if self_closing {
            return PValue::Other;
        }
        match name {
            "string" | "key" | "integer" | "real" | "date" | "data" => {
                PValue::Str(self.text_until_close(name))
            }
            "dict" => {
                let mut items = Vec::new();
                let mut key: Option<String> = None;
                while let Some((n, close, sc)) = self.next_tag() {
                    if close {
                        break;
                    }
                    if n == "key" {
                        key = Some(self.text_until_close("key"));
                    } else {
                        let v = self.value(&n, sc);
                        if let Some(k) = key.take() {
                            items.push((k, v));
                        }
                    }
                }
                PValue::Dict(items)
            }
            "array" => {
                let mut items = Vec::new();
                while let Some((n, close, sc)) = self.next_tag() {
                    if close {
                        break;
                    }
                    items.push(self.value(&n, sc));
                }
                PValue::Array(items)
            }
            _ => {
                let _ = self.text_until_close(name);
                PValue::Other
            }
        }
    }
}

fn get<'a>(d: &'a [(String, PValue)], key: &str) -> Option<&'a PValue> {
    d.iter().find(|(k, _)| k == key).map(|(_, v)| v)
}

fn parse_color_lenient(s: &str) -> Option<RgbaColor> {
    let s = s.trim();
    let hex = s.strip_prefix('#')?;
    let v: Vec<u8> = (0..hex.len())
        .step_by(2)
        .filter_map(|i| hex.get(i..i + 2).and_then(|p| u8::from_str_radix(p, 16).ok()))
        .collect();
    match (hex.len(), v.len()) {
        (6, 3) => Some(RgbaColor::new(v[0], v[1], v[2], 255)),
        (8, 4) => Some(RgbaColor::new(v[0], v[1], v[2], v[3])),
        (3, _) => {
            let c: Vec<u8> = hex
                .chars()
                .filter_map(|c| c.to_digit(16).map(|d| (d * 17) as u8))
                .collect();
            if c.len() == 3 {
                Some(RgbaColor::new(c[0], c[1], c[2], 255))
            } else {
                None
            }
        }
        _ => None,
    }
}

pub fn parse_tm_theme(content: &str) -> Option<Theme> {
    let mut r = XmlReader { s: content, pos: 0 };
    let root = loop {
        let (n, close, sc) = r.next_tag()?;
        if close || n == "plist" {
            continue;
        }
        break r.value(&n, sc);
    };
    let PValue::Dict(root) = root else { return None };
    let settings = match get(&root, "settings") {
        Some(PValue::Array(a)) => a.clone(),
        _ => Vec::new(),
    };
    let mut theme = Theme {
        background: RgbaColor::new(255, 255, 255, 255),
        foreground: RgbaColor::new(0, 0, 0, 255),
        rules: Vec::new(),
    };
    for item in settings {
        let PValue::Dict(d) = item else { continue };
        let Some(PValue::Dict(s)) = get(&d, "settings") else { continue };
        let scope = match get(&d, "scope") {
            Some(PValue::Str(s)) => Some(s.clone()),
            _ => None,
        };
        let fg = match get(s, "foreground") {
            Some(PValue::Str(c)) => parse_color_lenient(c),
            _ => None,
        };
        match scope {
            None => {
                if let Some(PValue::Str(c)) = get(s, "background") {
                    if let Some(c) = parse_color_lenient(c) {
                        theme.background = c;
                    }
                }
                if let Some(c) = fg {
                    theme.foreground = c;
                }
            }
            Some(scope) => {
                let font_style = match get(s, "fontStyle") {
                    Some(PValue::Str(f)) => Some(f.clone()),
                    _ => None,
                };
                let (bold, italic) = match &font_style {
                    Some(f) => (Some(f.contains("bold")), Some(f.contains("italic"))),
                    None => (None, None),
                };
                theme.rules.push(ThemeRule {
                    selectors: parse_selectors(&scope),
                    style: StyleModifier {
                        foreground: fg,
                        bold,
                        italic,
                    },
                });
            }
        }
    }
    Some(theme)
}

fn find_in_folder(folder: &Path, name: &str) -> Option<Theme> {
    let entries = std::fs::read_dir(folder).ok()?;
    let mut paths: Vec<_> = entries.filter_map(|e| e.ok()).map(|e| e.path()).collect();
    paths.sort();
    for p in paths {
        if p.extension().and_then(|e| e.to_str()) != Some("tmTheme") {
            continue;
        }
        if p.file_stem().and_then(|s| s.to_str()) == Some(name) {
            let content = std::fs::read_to_string(&p).ok()?;
            return parse_tm_theme(&content);
        }
    }
    None
}

/// Look up a theme by name.
pub fn load_theme(name: &str, folders: &[String], remote_dir: &Path) -> Result<Theme, String> {
    for folder in folders {
        if let Some(t) = find_in_folder(Path::new(folder), name) {
            return Ok(t);
        }
    }
    if let Some(t) = find_in_folder(remote_dir, name) {
        return Ok(t);
    }
    if name == "candy" {
        return Ok(candy());
    }
    Err(format!("Cannot find {} theme", name))
}
