fn is_ident_start(c: char) -> bool {
    c.is_alphabetic() || c == '_'
}
fn is_ident_char(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

struct Out {
    lines: Vec<Vec<Token>>,
}

impl Out {
    fn push(&mut self, text: &str, scope: &'static str) {
        let mut first = true;
        for part in text.split('\n') {
            if !first {
                self.lines.push(Vec::new());
            }
            first = false;
            if part.is_empty() {
                continue;
            }
            let line = self.lines.last_mut().unwrap();
            if let Some(last) = line.last_mut() {
                if last.scope == scope {
                    last.text.push_str(part);
                    continue;
                }
            }
            line.push(Token {
                text: part.to_string(),
                scope,
            });
        }
    }
}

fn starts_with_at(chars: &[char], i: usize, pat: &str) -> bool {
    let mut k = i;
    for pc in pat.chars() {
        if k >= chars.len() || chars[k] != pc {
            return false;
        }
        k += 1;
    }
    true
}

fn word_in(word: &str, list: &[&str], ci: bool) -> bool {
    if ci {
        list.iter().any(|w| w.eq_ignore_ascii_case(word))
    } else {
        list.contains(&word)
    }
}

fn lex_generic(code: &str, d: &Def, lang: Lang) -> Vec<Vec<Token>> {
    let chars: Vec<char> = code.chars().collect();
    let n = chars.len();
    let mut out = Out { lines: vec![Vec::new()] };
    let mut i = 0;
    let mut prev_word: String = String::new();
    let mut in_params = false;
    let mut param_depth = 0i32;
    let mut pending_fn = false;
    let mut line_start = true;
    while i < n {
        let c = chars[i];
        if c == '\n' {
            out.push("\n", "");
            i += 1;
            line_start = true;
            continue;
        }
        // comments
        let mut matched = false;
        for (open, close) in d.block_comments {
            if starts_with_at(&chars, i, open) {
                let mut j = i + open.chars().count();
                while j < n && !starts_with_at(&chars, j, close) {
                    j += 1;
                }
                j = (j + close.chars().count()).min(n);
                let s: String = chars[i..j].iter().collect();
                out.push(&s, "comment.block");
                i = j;
                matched = true;
                break;
            }
        }
        if matched {
            continue;
        }
        for lc in d.line_comments {
            let ok = if d.case_insensitive {
                let len = lc.chars().count();
                i + len <= n
                    && chars[i..i + len].iter().collect::<String>().eq_ignore_ascii_case(lc)
                    && (lc.chars().all(|c| !c.is_alphabetic())
                        || i + len >= n
                        || !is_ident_char(chars[i + len]))
            } else {
                starts_with_at(&chars, i, lc)
            };
            if ok {
                if *lc == "#" && lang == Lang::Shell && i > 0 && !chars[i - 1].is_whitespace() {
                    continue;
                }
                let mut j = i;
                while j < n && chars[j] != '\n' {
                    j += 1;
                }
                let s: String = chars[i..j].iter().collect();
                out.push(&s, "comment.line");
                i = j;
                matched = true;
                break;
            }
        }
        if matched {
            continue;
        }
        // preprocessor
        if d.preprocessor && c == '#' && line_start {
            let mut j = i + 1;
            while j < n && (chars[j] == ' ' || chars[j] == '\t') {
                j += 1;
            }
            while j < n && is_ident_char(chars[j]) {
                j += 1;
            }
            let s: String = chars[i..j].iter().collect();
            out.push(&s, "keyword.control.directive");
            i = j;
            // include <...>
            let mut k = i;
            while k < n && chars[k] == ' ' {
                k += 1;
            }
            if k < n && chars[k] == '<' {
                let mut e = k;
                while e < n && chars[e] != '>' && chars[e] != '\n' {
                    e += 1;
                }
                if e < n && chars[e] == '>' {
                    let sp: String = chars[i..k].iter().collect();
                    out.push(&sp, "");
                    let s: String = chars[k..=e].iter().collect();
                    out.push(&s, "string.quoted.other");
                    i = e + 1;
                }
            }
            line_start = false;
            continue;
        }
        if !c.is_whitespace() {
            line_start = false;
        }
        // strings
        if d.quotes.contains(c) {
            let triple = d.triple_quotes
                && i + 2 < n
                && chars[i + 1] == c
                && chars[i + 2] == c;
            let mut j = if triple { i + 3 } else { i + 1 };
            let mut segs: Vec<(usize, usize, &'static str)> = Vec::new();
            let mut seg_start = i;
            loop {
                if j >= n {
                    break;
                }
                let ch = chars[j];
                if ch == '\\' && j + 1 < n {
                    j += 2;
                    continue;
                }
                if !triple && ch == '\n' && c != '`' {
                    break;
                }
                if c != '\'' && ch == '%' && j + 1 < n && "sdfxcp".contains(chars[j + 1]) && matches!(lang, Lang::C | Lang::Cpp | Lang::ObjC) {
                    segs.push((seg_start, j, "string.quoted"));
                    segs.push((j, j + 2, "constant.other.placeholder"));
                    j += 2;
                    seg_start = j;
                    continue;
                }
                if triple {
                    if ch == c && j + 2 < n && chars[j + 1] == c && chars[j + 2] == c {
                        j += 3;
                        break;
                    }
                } else if ch == c {
                    j += 1;
                    break;
                }
                j += 1;
            }
            let j = j.min(n);
            segs.push((seg_start, j, if triple && lang == Lang::Python && prev_word.is_empty() { "comment.block.documentation" } else { "string.quoted" }));
            for (a, b, sc) in segs {
                if b > a {
                    let s: String = chars[a..b].iter().collect();
                    out.push(&s, sc);
                }
            }
            i = j;
            prev_word.clear();
            continue;
        }
        // numbers
        if c.is_ascii_digit() || (c == '.' && i + 1 < n && chars[i + 1].is_ascii_digit() && (i == 0 || !is_ident_char(chars[i - 1]))) {
            let mut j = i;
            if c == '0' && i + 1 < n && "xXbBoO".contains(chars[i + 1]) {
                j += 2;
                while j < n && (chars[j].is_ascii_hexdigit() || chars[j] == '_') {
                    j += 1;
                }
            } else {
                while j < n && (chars[j].is_ascii_digit() || chars[j] == '_' || chars[j] == '.') {
                    if chars[j] == '.' && (j + 1 >= n || !chars[j + 1].is_ascii_digit()) {
                        break;
                    }
                    j += 1;
                }
                if j < n && (chars[j] == 'e' || chars[j] == 'E') && j + 1 < n && (chars[j + 1].is_ascii_digit() || chars[j + 1] == '-') {
                    j += 2;
                    while j < n && chars[j].is_ascii_digit() {
                        j += 1;
                    }
                }
            }
            let s: String = chars[i..j].iter().collect();
            out.push(&s, "constant.numeric");
            i = j;
            // type suffix (rust)
            if lang == Lang::Rust {
                let mut k = i;
                while k < n && is_ident_char(chars[k]) {
                    k += 1;
                }
                if k > i {
                    let s: String = chars[i..k].iter().collect();
                    out.push(&s, "storage.type.numeric");
                    i = k;
                }
            }
            continue;
        }
        // variables like $x
        if d.dollar_vars && c == '$' {
            let mut j = i + 1;
            if j < n && chars[j] == '{' {
                while j < n && chars[j] != '}' && chars[j] != '\n' {
                    j += 1;
                }
                j = (j + 1).min(n);
            } else {
                while j < n && (is_ident_char(chars[j]) || (j == i + 1 && "@#?$!*0123456789".contains(chars[j]))) {
                    j += 1;
                }
            }
            let s: String = chars[i..j].iter().collect();
            let scope = if word_in(&s, d.lang_vars, false) { "variable.language" } else { "variable.other" };
            out.push(&s, scope);
            i = j;
            continue;
        }
        if d.at_annotations && c == '@' && i + 1 < n && is_ident_start(chars[i + 1]) {
            let mut j = i + 1;
            while j < n && is_ident_char(chars[j]) {
                j += 1;
            }
            let s: String = chars[i..j].iter().collect();
            out.push(&s, "meta.annotation");
            i = j;
            continue;
        }
        // identifiers
        if is_ident_start(c) {
            let mut j = i;
            while j < n && is_ident_char(chars[j]) {
                j += 1;
            }
            let word: String = chars[i..j].iter().collect();
            let mut k = j;
            while k < n && (chars[k] == ' ' || chars[k] == '\t') {
                k += 1;
            }
            let next = if k < n { chars[k] } else { '\0' };
            let ci = d.case_insensitive;
            let scope: &'static str = if word_in(&prev_word, d.fn_decl, ci) && !word_in(&word, d.keywords, ci) {
                pending_fn = true;
                "entity.name.function"
            } else if word_in(&prev_word, d.type_decl, ci) && !word_in(&word, d.keywords, ci) {
                d.type_decl_scope
            } else if word_in(&word, d.storage, ci) {
                "storage.type"
            } else if word_in(&word, d.keywords, ci) {
                "keyword.control"
            } else if word_in(&word, d.types, ci) {
                "storage.type.primitive"
            } else if word_in(&word, d.constants, ci) {
                "constant.language"
            } else if word_in(&word, d.lang_vars, ci) {
                if in_params { "variable.parameter" } else { "variable.language" }
            } else if word_in(&word, d.classes, ci) {
                "support.class"
            } else if lang == Lang::Rust && next == '!' {
                ""
            } else if in_params && (",)=:".contains(next) || (lang == Lang::Go && (is_ident_start(next) || next == '*' || next == '['))) {
                "variable.parameter"
            } else if next == '(' && word_in(&word, d.builtins, ci) {
                "support.function"
            } else if next == '(' && !d.call_scope.is_empty() {
                d.call_scope
            } else if d.capital_classes && word.chars().next().map(|c| c.is_uppercase()).unwrap_or(false) {
                "support.class"
            } else if (prev_word == "." || prev_word == "->") && matches!(lang, Lang::JavaScript | Lang::TypeScript) {
                "variable.other.property"
            } else {
                d.ident_scope
            };
            out.push(&word, scope);
            prev_word = word;
            i = j;
            continue;
        }
        // punctuation & operators
        let s = c.to_string();
        let scope: &'static str = match c {
            '{' | '}' => d.brace_scope,
            '(' => {
                if pending_fn {
                    in_params = true;
                    param_depth = 1;
                    pending_fn = false;
                } else if in_params {
                    param_depth += 1;
                }
                ""
            }
            ')' => {
                if in_params {
                    param_depth -= 1;
                    if param_depth <= 0 {
                        in_params = false;
                    }
                }
                ""
            }
            '.' => {
                if i + 1 < n && chars[i + 1] == '.' {
                    "keyword.operator"
                } else if matches!(lang, Lang::Rust | Lang::Go | Lang::C | Lang::Cpp | Lang::Json | Lang::Yaml | Lang::Toml | Lang::Shell) {
                    ""
                } else {
                    d.accessor_scope
                }
            }
            '=' | '+' | '-' | '*' | '/' | '%' | '<' | '>' | '!' | '&' | '|' | '^' | '~' | '?' => {
                if lang == Lang::Rust && c == '!' {
                    ""
                } else if matches!(lang, Lang::Json) {
                    ""
                } else {
                    "keyword.operator"
                }
            }
            ':' => {
                if i + 1 < n && chars[i + 1] == ':' && matches!(lang, Lang::Rust | Lang::Cpp) {
                    "keyword.operator"
                } else if i > 0 && chars[i - 1] == ':' && matches!(lang, Lang::Rust | Lang::Cpp) {
                    "keyword.operator"
                } else if lang == Lang::Go && i + 1 < n && chars[i + 1] == '=' {
                    "keyword.operator"
                } else {
                    ""
                }
            }
            '[' | ']' => {
                if lang == Lang::Java && ((c == '[' && i + 1 < n && chars[i + 1] == ']') || (c == ']' && i > 0 && chars[i - 1] == '[')) {
                    "keyword.operator"
                } else {
                    ""
                }
            }
            _ => "",
        };
        // `->`, `=>`
        if c == '=' && i + 1 < n && chars[i + 1] == '>' && matches!(lang, Lang::JavaScript | Lang::TypeScript) {
            out.push("=>", "storage.type.function.arrow");
            i += 2;
            prev_word = "=>".to_string();
            continue;
        }
        out.push(&s, scope);
        if !c.is_whitespace() {
            prev_word = s;
        }
        i += 1;
    }
    out.lines
}

fn lex_json(code: &str) -> Vec<Vec<Token>> {
    // keys vs values
    let chars: Vec<char> = code.chars().collect();
    let n = chars.len();
    let mut out = Out { lines: vec![Vec::new()] };
    let mut i = 0;
    while i < n {
        let c = chars[i];
        if c == '"' {
            let mut j = i + 1;
            while j < n && chars[j] != '"' && chars[j] != '\n' {
                if chars[j] == '\\' {
                    j += 1;
                }
                j += 1;
            }
            let j = (j + 1).min(n);
            let s: String = chars[i..j].iter().collect();
            let mut k = j;
            while k < n && chars[k].is_whitespace() {
                k += 1;
            }
            let scope = if k < n && chars[k] == ':' { "support.type.property-name.json" } else { "string.quoted.double.json" };
            out.push(&s, scope);
            i = j;
            continue;
        }
        if c == '-' || c.is_ascii_digit() {
            let mut j = i + 1;
            while j < n && (chars[j].is_ascii_digit() || ".eE+-".contains(chars[j])) {
                j += 1;
            }
            let s: String = chars[i..j].iter().collect();
            out.push(&s, "constant.numeric.json");
            i = j;
            continue;
        }
        if c.is_alphabetic() {
            let mut j = i;
            while j < n && chars[j].is_alphabetic() {
                j += 1;
            }
            let s: String = chars[i..j].iter().collect();
            out.push(&s, "constant.language.json");
            i = j;
            continue;
        }
        let s = c.to_string();
        out.push(&s, "");
        i += 1;
    }
    out.lines
}

fn lex_markup(code: &str) -> Vec<Vec<Token>> {
    let chars: Vec<char> = code.chars().collect();
    let n = chars.len();
    let mut out = Out { lines: vec![Vec::new()] };
    let mut i = 0;
    while i < n {
        if starts_with_at(&chars, i, "<!--") {
            let mut j = i + 4;
            while j < n && !starts_with_at(&chars, j, "-->") {
                j += 1;
            }
            let j = (j + 3).min(n);
            let s: String = chars[i..j].iter().collect();
            out.push(&s, "comment.block.html");
            i = j;
            continue;
        }
        if chars[i] == '<' && i + 1 < n && (chars[i + 1].is_alphabetic() || chars[i + 1] == '/' || chars[i + 1] == '!' || chars[i + 1] == '?') {
            let mut j = i + 1;
            if chars[j] == '/' || chars[j] == '!' || chars[j] == '?' {
                j += 1;
            }
            out.push(&chars[i..j].iter().collect::<String>(), "punctuation.definition.tag");
            let s = j;
            while j < n && (chars[j].is_alphanumeric() || "-_:.".contains(chars[j])) {
                j += 1;
            }
            out.push(&chars[s..j].iter().collect::<String>(), "entity.name.tag");
            // attributes
            while j < n && chars[j] != '>' {
                let c = chars[j];
                if c == '"' || c == '\'' {
                    let mut k = j + 1;
                    while k < n && chars[k] != c {
                        k += 1;
                    }
                    let k = (k + 1).min(n);
                    out.push(&chars[j..k].iter().collect::<String>(), "string.quoted");
                    j = k;
                } else if c.is_alphabetic() {
                    let mut k = j;
                    while k < n && (chars[k].is_alphanumeric() || "-_:".contains(chars[k])) {
                        k += 1;
                    }
                    out.push(&chars[j..k].iter().collect::<String>(), "entity.other.attribute-name");
                    j = k;
                } else {
                    out.push(&c.to_string(), "");
                    j += 1;
                }
            }
            if j < n {
                out.push(">", "punctuation.definition.tag");
                j += 1;
            }
            i = j;
            continue;
        }
        if chars[i] == '&' {
            let mut j = i + 1;
            while j < n && chars[j].is_alphanumeric() {
                j += 1;
            }
            if j < n && chars[j] == ';' {
                out.push(&chars[i..=j].iter().collect::<String>(), "constant.character.entity");
                i = j + 1;
                continue;
            }
        }
        out.push(&chars[i].to_string(), "");
        i += 1;
    }
    out.lines
}

fn lex_markdown(code: &str) -> Vec<Vec<Token>> {
    let mut out = Out { lines: vec![Vec::new()] };
    let mut first = true;
    let mut in_fence = false;
    for line in code.split('\n') {
        if !first {
            out.push("\n", "");
        }
        first = false;
        let t = line.trim_start();
        if t.starts_with("```") {
            in_fence = !in_fence;
            out.push(line, "punctuation.definition.raw");
        } else if in_fence {
            out.push(line, "markup.raw.block");
        } else if t.starts_with('#') {
            out.push(line, "markup.heading");
        } else if t.starts_with("> ") {
            out.push(line, "markup.quote");
        } else {
            let chars: Vec<char> = line.chars().collect();
            let mut i = 0;
            while i < chars.len() {
                if chars[i] == '`' {
                    let mut j = i + 1;
                    while j < chars.len() && chars[j] != '`' {
                        j += 1;
                    }
                    let j = (j + 1).min(chars.len());
                    out.push(&chars[i..j].iter().collect::<String>(), "markup.raw.inline");
                    i = j;
                } else if chars[i] == '*' && i + 1 < chars.len() && chars[i + 1] == '*' {
                    let mut j = i + 2;
                    while j + 1 < chars.len() && !(chars[j] == '*' && chars[j + 1] == '*') {
                        j += 1;
                    }
                    let j = (j + 2).min(chars.len());
                    out.push(&chars[i..j].iter().collect::<String>(), "markup.bold");
                    i = j;
                } else if (chars[i] == '-' || chars[i] == '*') && chars[..i].iter().all(|c| c.is_whitespace()) && i + 1 < chars.len() && chars[i + 1] == ' ' {
                    out.push(&chars[i].to_string(), "punctuation.definition.list");
                    i += 1;
                } else {
                    out.push(&chars[i].to_string(), "");
                    i += 1;
                }
            }
        }
    }
    out.lines
}

fn lex_diff(code: &str) -> Vec<Vec<Token>> {
    let mut out = Out { lines: vec![Vec::new()] };
    let mut first = true;
    for line in code.split('\n') {
        if !first {
            out.push("\n", "");
        }
        first = false;
        let scope = if line.starts_with("+++") || line.starts_with("---") {
            "meta.diff.header"
        } else if line.starts_with('+') {
            "markup.inserted"
        } else if line.starts_with('-') {
            "markup.deleted"
        } else if line.starts_with("@@") {
            "meta.diff.range"
        } else {
            ""
        };
        out.push(line, scope);
    }
    out.lines
}

fn plain(code: &str) -> Vec<Vec<Token>> {
    let mut out = Out { lines: vec![Vec::new()] };
    out.push(code, "");
    out.lines
}

pub fn highlight(code: &str, lang: Lang) -> Vec<Vec<Token>> {
    match lang {
        Lang::Json => lex_json(code),
        Lang::Html | Lang::Xml | Lang::Vue | Lang::Svelte => lex_markup(code),
        Lang::Markdown | Lang::Rst => lex_markdown(code),
        Lang::Diff => lex_diff(code),
        _ => match def_for(lang) {
            Some(d) => lex_generic(code, &d, lang),
            None => plain(code),
        },
    }
}
