//! Snapshot creation: layout of the window and its components, and
//! rendering into a pixmap.

use crate::components::background::draw_background;
use crate::config::{Code, HighlightLine, SnapshotConfig};
use crate::png;
use crate::render::blur::box_blur;
use crate::render::{Path, Pixmap};
use crate::syntax::{self, Lang};
use crate::text::{self, Family, Span};
use crate::theme::{load_theme, Theme};
use crate::utils::color::{parse_hex_color, RgbaColor};

#[derive(Clone, Debug)]
pub struct CommandLine {
    pub command: String,
    pub output: String,
}

#[derive(Clone, Debug)]
pub enum SnapshotInput {
    Code(Code),
    Commands(Vec<CommandLine>),
    Image(Vec<u8>),
}

pub struct ImageSnapshot {
    pub pixmap: Pixmap,
