fn base64(data: &[u8]) -> String {
    const T: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::with_capacity(data.len() * 4 / 3 + 4);
    for chunk in data.chunks(3) {
        let b = [chunk[0], *chunk.get(1).unwrap_or(&0), *chunk.get(2).unwrap_or(&0)];
        let v = ((b[0] as u32) << 16) | ((b[1] as u32) << 8) | b[2] as u32;
        out.push(T[(v >> 18) as usize & 63] as char);
        out.push(T[(v >> 12) as usize & 63] as char);
        out.push(if chunk.len() > 1 { T[(v >> 6) as usize & 63] as char } else { '=' });
        out.push(if chunk.len() > 2 { T[v as usize & 63] as char } else { '=' });
    }
    out
}

impl ImageSnapshot {
    pub fn png_data(&self) -> Vec<u8> {
        png::encode_rgba(self.pixmap.width, self.pixmap.height, &self.pixmap.to_rgba())
    }

    pub fn svg_data(&self) -> String {
        format!(
            "<svg xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"><image href=\"data:image/png;base64,{}\"/></svg>",
            base64(&self.png_data())
        )
    }

    pub fn html_data(&self) -> String {
        format!(
            "<img src=\"data:image/png;base64,{}\" />",
            base64(&self.png_data())
        )
    }
}

pub fn create_snapshot(
    config: &SnapshotConfig,
    input: &SnapshotInput,
    themes_dir: &std::path::Path,
) -> Result<ImageSnapshot, String> {
    let theme = load_theme(&config.theme, &config.themes_folders, themes_dir)?;
    match input {
        SnapshotInput::Code(code) => code_snapshot(config, &theme, code),
        SnapshotInput::Commands(cmds) => command_snapshot(config, &theme, cmds),
        SnapshotInput::Image(bytes) => image_snapshot(config, &theme, bytes),
    }
}

#[inline]
fn f(v: f32) -> f32 {
    v
}

// ---------------------------------------------------------------------------
// Code preparation

fn prepare_code(content: &str) -> String {
    let content = content.replace('\t', "  ");
    let lines: Vec<&str> = content.split('\n').collect();
    let indent = |l: &str| -> usize {
        match l.find(|c: char| !c.is_whitespace()) {
            Some(i) => l[..i].chars().count(),
            None => 0,
        }
    };
    let min_indent = lines.iter().map(|l| indent(l)).min().unwrap_or(0);
    let dedented: Vec<String> = if min_indent > 0 {
        lines
            .iter()
            .map(|l| l.chars().skip(min_indent).collect::<String>())
            .collect()
    } else {
        lines.iter().map(|s| s.to_string()).collect()
    };
    let joined = dedented.join("\n");
    joined.trim_end_matches(['\n', '\r']).to_string()
}

/// Split text into lines the way the text layout does (`\r\n`, `\n`, `\r`).
fn split_lines(text: &str) -> Vec<String> {
    let mut lines = Vec::new();
    let mut cur = String::new();
    let mut chars = text.chars().peekable();
    while let Some(c) = chars.next() {
        match c {
            '\r' => {
                if chars.peek() == Some(&'\n') {
                    chars.next();
                }
                lines.push(std::mem::take(&mut cur));
            }
            '\n' => lines.push(std::mem::take(&mut cur)),
            _ => cur.push(c),
        }
    }
    lines.push(cur);
    lines
}

fn detect_lang(code: &Code) -> Result<Lang, String> {
    if let Some(l) = &code.language {
        return Ok(syntax::find_by_token(l).unwrap_or(Lang::Plain));
    }
    if let Some(p) = &code.file_path {
        return syntax::find_for_file(p);
    }
    let first = code.content.split('\n').next().unwrap_or("");
    Ok(syntax::find_by_first_line(first).unwrap_or(Lang::Plain))
}

fn spans_for_lines(text: &str, lang: Lang, theme: &Theme) -> Vec<Vec<Span>> {
    let tokens = syntax::highlight(text, lang);
    let mut result: Vec<Vec<Span>> = Vec::new();
    for line in tokens {
        let mut spans = Vec::new();
        for tok in line {
            let stack: Vec<&str> = if tok.scope.is_empty() {
                vec!["source"]
            } else {
                vec!["source", tok.scope]
            };
            let style = theme.style_for(&stack);
            let text = tok.text.replace('\r', "");
            spans.push(Span {
                text,
                color: style.foreground,
                bold: style.bold,
                italic: style.italic,
            });
        }
        result.push(spans);
    }
    result
}

// ---------------------------------------------------------------------------
// Window layout shared by code and command snapshots

struct Frame {
    scale: f32,
    margin_x: f32,
    margin_y: f32,
    window_w: f32,
    window_h: f32,
    width_px: u32,
    height_px: u32,
    has_watermark: bool,
}

impl Frame {
    fn new(config: &SnapshotConfig, content_w: f32, window_h: f32) -> Frame {
        let s = config.scale_factor as f32;
        let mx = config.window.margin.x;
        let my = config.window.margin.y;
        let window_w = f(content_w + 32.0).max(354.0);
        let has_watermark = config.watermark.is_some() && my >= 82.0;
        let wm_h = if has_watermark { 72.0 } else { 0.0 };
        let total_w = f(f(window_w + mx) + mx);
        let total_h = f(f(f(window_h + my) + my) + wm_h);
        let width_px = (total_w * s) as u32;
        let height_px = (total_h * s) as u32;
        Frame {
            scale: s,
            margin_x: mx,
            margin_y: my,
            window_w,
            window_h,
            width_px: width_px.max(1),
            height_px: height_px.max(1),
            has_watermark,
        }
    }
}

fn draw_frame(pixmap: &mut Pixmap, config: &SnapshotConfig, theme: &Theme, fr: &Frame) {
    draw_background(pixmap, &config.background);
    let s = fr.scale;
    // shadow
    let shadow_color = parse_hex_color(&config.window.shadow.color);
    let sw = ((fr.width_px as f32) / s).ceil().max(1.0) as u32;
    let sh = ((fr.height_px as f32) / s).ceil().max(1.0) as u32;
    let mut shadow = Pixmap::new(sw, sh);
    shadow.fill_path(
        &Path::rect(fr.margin_x, fr.margin_y + 21.0, fr.window_w, fr.window_h),
        shadow_color,
    );
    box_blur(&mut shadow, config.window.shadow.radius);
    pixmap.draw_pixmap_nearest(&shadow, s);
    // window
    let r = config.window.radius;
    let win = Path::rounded_rect(fr.margin_x, fr.margin_y, fr.window_w, fr.window_h, r)
        .transform(s, s, 0.0, 0.0);
    pixmap.fill_path(&win, theme.background);
    // border
    let bw = config.window.border.width;
    if bw > 0.0 {
        let border_color = parse_hex_color(&config.window.border.color);
        let inset = bw * 1.5;
        let (x, y) = (fr.margin_x + inset, fr.margin_y + inset);
        let (w, h) = (fr.window_w - inset * 2.0, fr.window_h - inset * 2.0);
        let half = bw / 2.0;
        let mut ring = Path::new();
        ring.add_rounded_rect(x - half, y - half, w + bw, h + bw, r + half, false);
        ring.add_rounded_rect(x + half, y + half, w - bw, h - bw, (r - half).max(0.0), true);
        let ring = ring.finish().transform(s, s, 0.0, 0.0);
        pixmap.fill_path(&ring, border_color);
    }
    // mac window bar
    if config.window.mac_window_bar {
        let colors = ["#FF5E57", "#FFBA2E", "#2BC841"];
        for (i, c) in colors.iter().enumerate() {
            let cx = fr.margin_x + 16.0 + 6.0 + 16.0 * i as f32;
            let cy = fr.margin_y + 16.0 + 6.0;
            let circle = Path::circle(cx * s, cy * s, 6.0 * s);
            pixmap.fill_path(&circle, parse_hex_color(c));
        }
    }
}

fn draw_title(pixmap: &mut Pixmap, config: &SnapshotConfig, fr: &Frame, row_top: f32) {
    let Some(title) = &config.title else { return };
    if title.is_empty() {
        return;
    }
    let s = fr.scale;
    let family = text::family_for(&config.window.title_config.font_family);
    let size = 10.0 * s;
    let w = text::line_width_em(family, title) * size;
    let x = fr.margin_x * s + (fr.window_w * s - w) / 2.0;
    let center = (row_top + 4.83) * s;
    let color = parse_hex_color(&config.window.title_config.color);
    let spans = [Span {
        text: title.clone(),
        color,
        bold: false,
        italic: false,
    }];
    text::draw_line(pixmap, family, &spans, (x, center), 0.0, 0.0, 0.0, size);
}

fn draw_watermark(pixmap: &mut Pixmap, config: &SnapshotConfig, fr: &Frame) {
    if !fr.has_watermark {
        return;
    }
    let Some(wm) = &config.watermark else { return };
    if wm.content.is_empty() {
        return;
    }
    let s = fr.scale;
    let family = text::family_for(&wm.font_family);
    let size = 30.0 * s;
    let w = text::line_width_em(family, &wm.content) * size;
    let x = (pixmap.width as f32 - w) / 2.0;
    let center = (fr.margin_y + fr.window_h + 66.83) * s;
    let color = parse_hex_color(&wm.color);
    let spans = [Span {
        text: wm.content.clone(),
        color,
        bold: false,
        italic: false,
    }];
    text::draw_line(pixmap, family, &spans, (x.round(), center), 0.0, 0.0, 0.0, size);
}

fn top_layout(config: &SnapshotConfig) -> (f32, f32, f32) {
    // (padding top, title row height, title row width)
    let bar = config.window.mac_window_bar;
    let title_w = config
        .title
        .as_ref()
        .map(|t| t.len() as f32 * 6.0)
        .unwrap_or(0.0);
    if bar {
        (16.0, 22.0, 62.0 + title_w)
    } else if config.title.is_some() {
        (14.0, 14.0, title_w)
    } else {
        (14.0, 0.0, 0.0)
    }
}

// ---------------------------------------------------------------------------
// Code snapshot

fn code_snapshot(config: &SnapshotConfig, theme: &Theme, code: &Code) -> Result<ImageSnapshot, String> {
    let lang = detect_lang(code)?;
    let s = config.scale_factor as f32;
    let text_content = prepare_code(&code.content);
    let lines = split_lines(&text_content);
    let line_count = lines.len().max(1);
    let max_chars = lines.iter().map(|l| l.chars().count()).max().unwrap_or(0);
    let font_px = f(12.5 * s);
    let advance = f(font_px * 1200.0 / 2048.0);
    let tp = f(max_chars as f32 * advance).ceil();
    let code_w = f(tp / s);
    let (ln_w, ln_digits) = match code.start_line_number {
        Some(start) => {
            let last = start as u64 + line_count as u64 - 1;
            let digits = last.to_string().len();
            (f(f(digits as f32 * 9.05) + 10.0), digits)
        }
        None => (0.0, 0),
    };
    let (pad_top, title_h, title_row_w) = top_layout(config);
    let breadcrumbs = if config.code_config.breadcrumbs.enable {
        code.file_path.clone()
    } else {
        None
    };
    let bc_h = if breadcrumbs.is_some() { 15.0 } else { 0.0 };
    let bc_w = breadcrumbs.as_ref().map(|p| p.len() as f32 * 8.0).unwrap_or(0.0);
    let code_h = 18.0 * line_count as f32;
    let content_w = f(code_w + ln_w).max(title_row_w).max(bc_w);
    let window_h = pad_top + title_h + bc_h + code_h + 16.0;
    let fr = Frame::new(config, content_w, window_h);
    let mut pixmap = Pixmap::new(fr.width_px, fr.height_px);
    draw_frame(&mut pixmap, config, theme, &fr);

    let win_x = fr.margin_x;
    let win_y = fr.margin_y;
    let row_top = win_y + pad_top;
    draw_title(&mut pixmap, config, &fr, row_top);

    // breadcrumbs
    if let Some(path) = &breadcrumbs {
        let bc = &config.code_config.breadcrumbs;
        let parts: Vec<&str> = path.split('/').collect();
        let text_value = parts.join(&bc.separator);
        let color = parse_hex_color(&bc.color);
        let family = text::family_for(&bc.font_family);
        let spans = [Span {
            text: text_value,
            color,
            bold: false,
            italic: false,
        }];
        let top = row_top + title_h;
        text::draw_line(
            &mut pixmap,
            family,
            &spans,
            ((win_x + 16.0) * s, top * s),
            0.0,
            0.0,
            15.0 * s,
            font_px,
        );
    }

    let code_top = row_top + title_h + bc_h;
    // highlighted lines
    for hl in &code.highlight_lines {
        let (start, end, color) = match hl {
            HighlightLine::Single(n, c) => (*n as usize, *n as usize, c),
            HighlightLine::Range(a, b, c) => ((*a).min(*b) as usize, (*a).max(*b) as usize, c),
        };
        if start == 0 {
            continue;
        }
        let color = parse_hex_color(color);
        let end = end.min(line_count);
        for row in start..=end {
            let y = code_top + (row - 1) as f32 * 18.0;
            pixmap.fill_rect(
                (win_x + 2.0) * s,
                y * s,
                (fr.window_w - 4.0) * s,
                18.0 * s,
                color,
            );
        }
    }

    // line numbers
    if let Some(start) = code.start_line_number {
        let color = parse_hex_color(&config.line_number_color);
        for i in 0..line_count {
            let number = format!("{:>width$}", start as u64 + i as u64, width = ln_digits);
            let spans = [Span {
                text: number,
                color,
                bold: false,
                italic: false,
            }];
            text::draw_line(
                &mut pixmap,
                Family::Mono,
                &spans,
                ((win_x + 16.0) * s, code_top * s),
                0.0,
                i as f32 * 18.0 * s,
                18.0 * s,
                font_px,
            );
        }
    }

    // code
    let family = text::family_for(&config.code_config.font_family);
    let family = if family == Family::Script { Family::Script } else { Family::Mono };
    let spans = spans_for_lines(&text_content, lang, theme);
    let origin = ((win_x + 16.0 + ln_w) * s, code_top * s);
    for (i, line) in spans.iter().enumerate() {
        text::draw_line(
            &mut pixmap,
            if family == Family::Script { Family::Mono } else { family },
            line,
            origin,
            0.0,
            i as f32 * 18.0 * s,
            18.0 * s,
            font_px,
        );
    }

    draw_watermark(&mut pixmap, config, &fr);
    Ok(ImageSnapshot { pixmap })
}

// ---------------------------------------------------------------------------
// Command snapshot

fn command_snapshot(
    config: &SnapshotConfig,
    theme: &Theme,
    cmds: &[CommandLine],
) -> Result<ImageSnapshot, String> {
    let s = config.scale_factor as f32;
    let prompt = RgbaColor::new(0xf7, 0x8f, 0xb3, 0xff);
    let cmd_color = RgbaColor::new(0x98, 0xc3, 0x79, 0xff);
    let arg_color = RgbaColor::new(0xff, 0xff, 0xff, 0xff);
    let out_color = RgbaColor::new(0x97, 0x9e, 0xab, 0xff);
    let mut lines: Vec<Vec<Span>> = Vec::new();
    let span = |t: &str, c: RgbaColor| Span {
        text: t.to_string(),
        color: c,
        bold: false,
        italic: false,
    };
    for cmd in cmds {
        let trimmed = cmd.command.trim_start();
        let (name, rest) = match trimmed.find(char::is_whitespace) {
            Some(i) => (&trimmed[..i], &trimmed[i..]),
            None => (trimmed, ""),
        };
        lines.push(vec![span("❯ ", prompt), span(name, cmd_color), span(rest, arg_color)]);
        let output = cmd.output.strip_suffix('\n').unwrap_or(&cmd.output);
        for l in split_lines(output) {
            lines.push(vec![span(&l, out_color)]);
        }
    }
    let max_chars = lines
        .iter()
        .map(|l| l.iter().map(|s| s.text.chars().count()).sum::<usize>())
        .max()
        .unwrap_or(0);
    let font_px = f(12.5 * s);
    let advance = f(font_px * 1200.0 / 2048.0);
    let tp = f(max_chars as f32 * advance).ceil();
    let code_w = f(tp / s);
    let (pad_top, title_h, title_row_w) = top_layout(config);
    let code_h = 20.0 * lines.len() as f32;
    let content_w = code_w.max(title_row_w);
    let window_h = pad_top + title_h + code_h + 16.0;
    let fr = Frame::new(config, content_w, window_h);
    let mut pixmap = Pixmap::new(fr.width_px, fr.height_px);
    draw_frame(&mut pixmap, config, theme, &fr);
    let row_top = fr.margin_y + pad_top;
    draw_title(&mut pixmap, config, &fr, row_top);
    let code_top = row_top + title_h;
    let origin = ((fr.margin_x + 16.0) * s, code_top * s);
    for (i, line) in lines.iter().enumerate() {
        text::draw_line(
            &mut pixmap,
            Family::Mono,
            line,
            origin,
            0.0,
            i as f32 * 20.0 * s,
            20.0 * s,
            font_px,
        );
    }
    draw_watermark(&mut pixmap, config, &fr);
    Ok(ImageSnapshot { pixmap })
}

// ---------------------------------------------------------------------------
// Image snapshot

fn image_snapshot(config: &SnapshotConfig, theme: &Theme, bytes: &[u8]) -> Result<ImageSnapshot, String> {
    let img = png::decode(bytes)?;
    let s = config.scale_factor as f32;
    let mx = config.window.margin.x;
    let my = config.window.margin.y;
    let has_watermark = config.watermark.is_some() && my >= 82.0;
    let wm_h = if has_watermark { 72.0 } else { 0.0 };
    let w = img.width as f32;
    let h = img.height as f32;
    let width_px = ((w + mx * 2.0) * s) as u32;
    let height_px = ((h + my * 2.0 + wm_h) * s) as u32;
    let mut pixmap = Pixmap::new(width_px.max(1), height_px.max(1));
    draw_background(&mut pixmap, &config.background);
    let _ = theme;
    // bilinear upscale of the image into place, clipped by a rounded rect
    let clip = Path::rounded_rect(mx * s, my * s, w * s, h * s, config.window.radius * s);
    if let Some(mask) = crate::render::raster::rasterize(&clip, pixmap.width as usize, pixmap.height as usize) {
        let iw = img.width as usize;
        let ih = img.height as usize;
        let sample = |x: f32, y: f32| -> [f32; 4] {
            let fx = (x - 0.5).max(0.0);
            let fy = (y - 0.5).max(0.0);
            let x0 = (fx.floor() as usize).min(iw - 1);
            let y0 = (fy.floor() as usize).min(ih - 1);
            let x1 = (x0 + 1).min(iw - 1);
            let y1 = (y0 + 1).min(ih - 1);
            let tx = fx - x0 as f32;
            let ty = fy - y0 as f32;
            let px = |xx: usize, yy: usize| -> [f32; 4] {
                let i = (yy * iw + xx) * 4;
                let a = img.rgba[i + 3] as f32 / 255.0;
                [
                    img.rgba[i] as f32 / 255.0 * a,
                    img.rgba[i + 1] as f32 / 255.0 * a,
                    img.rgba[i + 2] as f32 / 255.0 * a,
                    a,
                ]
            };
            let (a, b, c, d) = (px(x0, y0), px(x1, y0), px(x0, y1), px(x1, y1));
            let mut o = [0f32; 4];
            for k in 0..4 {
                o[k] = (a[k] * (1. - tx) + b[k] * tx) * (1. - ty) + (c[k] * (1. - tx) + d[k] * tx) * ty;
            }
            o
        };
        if iw > 0 && ih > 0 {
            for yy in 0..mask.h {
                for xx in 0..mask.w {
                    let cov = mask.data[yy * mask.w + xx];
                    if cov <= 0.0 {
                        continue;
                    }
                    let px = mask.x0 as usize + xx;
                    let py = mask.y0 as usize + yy;
                    let ix = (px as f32 + 0.5 - mx * s) / s;
                    let iy = (py as f32 + 0.5 - my * s) / s;
                    let c = sample(ix, iy);
                    let di = (py * pixmap.width as usize + px) * 4;
                    let sa = c[3] * cov;
                    for k in 0..4 {
                        let sv = c[k] * cov;
                        let dv = pixmap.data[di + k] as f32 / 255.0;
                        pixmap.data[di + k] = ((sv + dv * (1.0 - sa)).clamp(0., 1.) * 255.0 + 0.5) as u8;
                    }
                }
            }
        }
    }
    let fr = Frame {
        scale: s,
        margin_x: mx,
        margin_y: my,
        window_w: w,
        window_h: h,
        width_px,
        height_px,
        has_watermark,
    };
    draw_watermark(&mut pixmap, config, &fr);
    Ok(ImageSnapshot { pixmap })
}
