//! Text rendering. The original fonts are not available, so glyphs are
//! drawn with substitute fonts while keeping the metrics of the original
//! fonts (CaskaydiaCove Nerd Font for code, Pacifico for the watermark).
//! Text that falls back to system fonts (DejaVu Sans) is drawn with the
//! real font.

use crate::font::{self, glyph_path, FontKind};
use crate::render::raster::rasterize;
use crate::render::Pixmap;
use crate::utils::color::RgbaColor;

/// CaskaydiaCove metrics (font units per em: 2048).
pub const MONO_ADVANCE: f32 = 1200.0 / 2048.0;
pub const MONO_ASCENT: f32 = 1900.0 / 2048.0;
pub const MONO_DESCENT: f32 = 480.0 / 2048.0;

/// Pacifico vertical metrics.
pub const SCRIPT_ASCENT: f32 = 1.303;
pub const SCRIPT_DESCENT: f32 = 0.453;

/// DejaVu Sans vertical metrics.
pub const SANS_ASCENT: f32 = 1901.0 / 2048.0;
pub const SANS_DESCENT: f32 = 483.0 / 2048.0;

/// Typeface used to draw a run of text.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Face {
    /// The code font (monospace cells).
    Mono,
    /// The script font of the watermark.
    Script,
    /// System fallback font (DejaVu Sans).
    Sans,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Weight {
    Regular,
    Bold,
}

fn is_code_font(name: &str) -> bool {
    let lower = name.to_lowercase();
    lower.contains("caskaydia") || lower.contains("cascadia")
}

/// Face used for regular weight text of a font family.
pub fn regular_face(family: &str) -> Face {
    if family.to_lowercase().contains("pacifico") {
        Face::Script
    } else if is_code_font(family) || family.to_lowercase().contains("mono") {
        Face::Mono
    } else {
        Face::Sans
    }
}

/// Face used for bold text of a font family (Pacifico has no bold style,
/// the system font is used instead).
pub fn bold_face(family: &str) -> Face {
    if is_code_font(family) || family.to_lowercase().contains("mono") {
        Face::Mono
    } else {
        Face::Sans
    }
}

/// A run of text with a single style.
#[derive(Clone, Debug)]
pub struct Span {
    pub text: String,
    pub color: RgbaColor,
    pub bold: bool,
    pub italic: bool,
}

impl Span {
    pub fn plain(text: &str, color: RgbaColor) -> Span {
        Span {
            text: text.to_string(),
            color,
            bold: false,
            italic: false,
        }
    }
}

const SCRIPT_X_SCALE: f32 = 0.83;
const SCRIPT_Y_SCALE: f32 = 1.45;

fn script_advance(ch: char) -> f32 {
    let f = font::font(FontKind::SansBold);
    f.char_advance(ch) * SCRIPT_X_SCALE
}

/// Advance of a character in em units.
pub fn char_advance(face: Face, bold: bool, ch: char) -> f32 {
    match face {
        Face::Mono => MONO_ADVANCE,
        Face::Script => script_advance(ch),
        Face::Sans => {
            let k = if bold { FontKind::SansBold } else { FontKind::Sans };
            font::font(k).char_advance(ch)
        }
    }
}

/// Width of a line of text in em units.
pub fn line_width_em(face: Face, bold: bool, text: &str) -> f32 {
    text.chars().map(|c| char_advance(face, bold, c)).sum()
}

fn metrics(face: Face) -> (f32, f32) {
    match face {
        Face::Mono => (MONO_ASCENT, MONO_DESCENT),
        Face::Script => (SCRIPT_ASCENT, SCRIPT_DESCENT),
        Face::Sans => (SANS_ASCENT, SANS_DESCENT),
    }
}

/// Subpixel binning as performed by the glyph cache (quarter pixels).
fn subpixel(pos: f32) -> (i32, f32) {
    let trunc = pos.trunc();
    let fract = pos - trunc;
    let t = trunc as i32;
    if pos < 0.0 {
        return (t, 0.0);
    }
    if fract < 0.125 {
        (t, 0.0)
    } else if fract < 0.375 {
        (t, 0.25)
    } else if fract < 0.625 {
        (t, 0.5)
    } else if fract < 0.875 {
        (t, 0.75)
    } else {
        (t + 1, 0.0)
    }
}

/// Glyph coverage bitmap.
struct GlyphImage {
    left: i32,
    top: i32,
    w: usize,
    h: usize,
    data: Vec<f32>,
}

fn render_glyph(face: Face, ch: char, bold: bool, italic: bool, size: f32, bin_x: f32) -> Option<GlyphImage> {
    if ch.is_whitespace() || ch.is_control() {
        return None;
    }
    let (kind, hscale, vscale) = match face {
        Face::Mono => {
            let k = if bold { FontKind::MonoBold } else { FontKind::Mono };
            let adv = font::font(k).char_advance('0');
            (k, if adv > 0.0 { MONO_ADVANCE / adv } else { 1.0 }, 1.0)
        }
        Face::Script => (FontKind::SansBold, SCRIPT_X_SCALE, SCRIPT_Y_SCALE),
        Face::Sans => (if bold { FontKind::SansBold } else { FontKind::Sans }, 1.0, 1.0),
    };
    let mut f = font::font(kind);
    if !f.has_glyph(ch) {
        let alt = match kind {
            FontKind::Mono | FontKind::MonoBold => FontKind::Sans,
            _ => FontKind::Mono,
        };
        if font::font(alt).has_glyph(ch) {
            f = font::font(alt);
        }
    }
    let path = if f.has_glyph(ch) {
        let p = glyph_path(f, ch, size, 0.0, 0.0, hscale)?;
        let shear = if italic || face == Face::Script { 0.18 } else { 0.0 };
        p.transform_affine(1.0, -shear, 0.0, vscale, bin_x, 0.0)
    } else {
        // missing glyph box
        let w = size * MONO_ADVANCE;
        let mut p = crate::render::Path::new();
        let (x0, x1) = (bin_x + w * 0.1, bin_x + w * 0.9);
        let (y0, y1) = (-size * 0.75, size * 0.05);
        let t = (size * 0.06).max(1.0);
        p.add_rounded_rect(x0, y0, x1 - x0, y1 - y0, 0.0, false);
        p.add_rounded_rect(x0 + t, y0 + t, x1 - x0 - 2. * t, y1 - y0 - 2. * t, 0.0, true);
        p.finish()
    };
    let mut minx = f32::MAX;
    let mut miny = f32::MAX;
    let mut maxx = f32::MIN;
    let mut maxy = f32::MIN;
    for c in &path.contours {
        for p in c {
            minx = minx.min(p.x);
            miny = miny.min(p.y);
            maxx = maxx.max(p.x);
            maxy = maxy.max(p.y);
        }
    }
    if minx > maxx {
        return None;
    }
    let left = minx.floor() as i32;
    let top = miny.floor() as i32;
    let right = maxx.ceil() as i32;
    let bottom = maxy.ceil() as i32;
    let w = (right - left).max(1) as usize;
    let h = (bottom - top).max(1) as usize;
    let shifted = path.transform(1.0, 1.0, -(left as f32), -(top as f32));
    let mask = rasterize(&shifted, w, h)?;
    let mut data = vec![0f32; w * h];
    for y in 0..mask.h {
        for x in 0..mask.w {
            let gx = mask.x0 as usize + x;
            let gy = mask.y0 as usize + y;
            if gx < w && gy < h {
                data[gy * w + gx] = mask.data[y * mask.w + x];
            }
        }
    }
    Some(GlyphImage { left, top, w, h, data })
}

/// Blend a 1x1 rectangle at a fractional position (anti-aliased).
fn blend_unit_rect(pixmap: &mut Pixmap, x: f32, y: f32, color: RgbaColor) {
    let fx = x.floor();
    let fy = y.floor();
    let dx = x - fx;
    let dy = y - fy;
    let ix = fx as i32;
    let iy = fy as i32;
    if dx.abs() < 1e-4 && dy.abs() < 1e-4 {
        pixmap.blend_pixel(ix, iy, color);
        return;
    }
    let parts = [
        (ix, iy, (1. - dx) * (1. - dy)),
        (ix + 1, iy, dx * (1. - dy)),
        (ix, iy + 1, (1. - dx) * dy),
        (ix + 1, iy + 1, dx * dy),
    ];
    for (px, py, cov) in parts {
        if cov <= 1e-4 {
            continue;
        }
        pixmap.blend_pixel_coverage(px, py, color, cov);
    }
}

/// A text buffer: a list of lines laid out from an origin.
pub struct TextBox {
    /// Physical position of the buffer origin.
    pub origin: (f32, f32),
    /// Physical font size.
    pub size: f32,
    /// Physical line height.
    pub line_height: f32,
    /// Face of regular text and of bold text.
    pub face: Face,
    pub bold_face: Face,
    /// Width of the buffer for alignment (center) or `None` for left.
    pub center_width: Option<f32>,
}

impl TextBox {
    fn span_face(&self, span: &Span) -> Face {
        if span.bold {
            self.bold_face
        } else {
            self.face
        }
    }

    pub fn line_width(&self, spans: &[Span]) -> f32 {
        spans
            .iter()
            .map(|s| line_width_em(self.span_face(s), s.bold, &s.text) * self.size)
            .sum()
    }

    /// Draw a line of spans at line index `index`.
    pub fn draw_line(&self, pixmap: &mut Pixmap, index: usize, spans: &[Span]) {
        // line metrics from the faces used on the line
        let mut ascent: f32 = 0.0;
        let mut descent: f32 = 0.0;
        for s in spans {
            let (a, d) = metrics(self.span_face(s));
            ascent = ascent.max(a * self.size);
            descent = descent.max(d * self.size);
        }
        if spans.is_empty() {
            let (a, d) = metrics(self.face);
            ascent = a * self.size;
            descent = d * self.size;
        }
        let line_top = index as f32 * self.line_height;
        let centering = (self.line_height - (ascent + descent)) / 2.0;
        let line_y = line_top + centering + ascent;
        let gy = line_y.trunc();
        let mut x = match self.center_width {
            Some(w) => (w - self.line_width(spans)) / 2.0,
            None => 0.0,
        };
        for span in spans {
            let face = self.span_face(span);
            for ch in span.text.chars() {
                let adv = char_advance(face, span.bold, ch) * self.size;
                let (ix, bin) = subpixel(x);
                if let Some(img) = render_glyph(face, ch, span.bold, span.italic, self.size, bin) {
                    for yy in 0..img.h {
                        for xx in 0..img.w {
                            let cov = img.data[yy * img.w + xx];
                            if cov <= 0.0 {
                                continue;
                            }
                            let a = ((cov * span.color.a as f32) + 0.5) as u32;
                            if a == 0 {
                                continue;
                            }
                            let px = (ix + img.left + xx as i32) as f32;
                            let py = gy + (img.top + yy as i32) as f32;
                            let c = RgbaColor::new(span.color.r, span.color.g, span.color.b, a.min(255) as u8);
                            blend_unit_rect(pixmap, self.origin.0 + px, self.origin.1 + py, c);
                        }
                    }
                }
                x += adv;
            }
        }
    }
}
