    let mut miny = f32::MAX;
    let mut maxx = f32::MIN;
    let mut maxy = f32::MIN;
    for c in &path.contours {
        for p in c {
            minx = minx.min(p.x);
            miny = miny.min(p.y);
            maxx = maxx.max(p.x);
            maxy = maxy.max(p.y);
        }
    }
    if minx > maxx {
        return None;
    }
    let left = minx.floor() as i32;
    let top = miny.floor() as i32;
    let right = maxx.ceil() as i32;
    let bottom = maxy.ceil() as i32;
    let w = (right - left).max(1) as usize;
    let h = (bottom - top).max(1) as usize;
    let shifted = path.transform(1.0, 1.0, -(left as f32), -(top as f32));
    let mask = rasterize(&shifted, w, h)?;
    let mut data = vec![0f32; w * h];
    for y in 0..mask.h {
        for x in 0..mask.w {
            let gx = mask.x0 as usize + x;
            let gy = mask.y0 as usize + y;
            if gx < w && gy < h {
                data[gy * w + gx] = mask.data[y * mask.w + x];
            }
        }
    }
    Some(GlyphImage { left, top, w, h, data })
}

/// Blend a 1x1 rectangle at a fractional position (anti-aliased).
fn blend_unit_rect(pixmap: &mut Pixmap, x: f32, y: f32, color: RgbaColor) {
    let fx = x.floor();
    let fy = y.floor();
    let dx = x - fx;
    let dy = y - fy;
    let ix = fx as i32;
    let iy = fy as i32;
    if dx.abs() < 1e-4 && dy.abs() < 1e-4 {
        pixmap.blend_pixel(ix, iy, color);
        return;
    }
    let parts = [
        (ix, iy, (1. - dx) * (1. - dy)),
        (ix + 1, iy, dx * (1. - dy)),
        (ix, iy + 1, (1. - dx) * dy),
        (ix + 1, iy + 1, dx * dy),
    ];
    for (px, py, cov) in parts {
        if cov <= 1e-4 {
            continue;
        }
        pixmap.blend_pixel_coverage(px, py, color, cov);
    }
}

/// A text buffer: a list of lines laid out from an origin.
pub struct TextBox {
    /// Physical position of the buffer origin.
    pub origin: (f32, f32),
    /// Physical font size.
    pub size: f32,
    /// Physical line height.
    pub line_height: f32,
    /// Face of regular text and of bold text.
    pub face: Face,
    pub bold_face: Face,
    /// Width of the buffer for alignment (center) or `None` for left.
    pub center_width: Option<f32>,
}

impl TextBox {
    fn span_face(&self, span: &Span) -> Face {
        if span.bold {
            self.bold_face
        } else {
            self.face
        }
    }

    pub fn line_width(&self, spans: &[Span]) -> f32 {
        spans
            .iter()
            .map(|s| line_width_em(self.span_face(s), s.bold, &s.text) * self.size)
            .sum()
    }

    /// Draw a line of spans at line index `index`.
    pub fn draw_line(&self, pixmap: &mut Pixmap, index: usize, spans: &[Span]) {
        // line metrics from the faces used on the line
        let mut ascent: f32 = 0.0;
        let mut descent: f32 = 0.0;
        for s in spans {
            let (a, d) = metrics(self.span_face(s));
            ascent = ascent.max(a * self.size);
            descent = descent.max(d * self.size);
        }
        if spans.is_empty() {
            let (a, d) = metrics(self.face);
            ascent = a * self.size;
            descent = d * self.size;
        }
        let line_top = index as f32 * self.line_height;
        let centering = (self.line_height - (ascent + descent)) / 2.0;
        let line_y = line_top + centering + ascent;
        let gy = line_y.trunc();
        let mut x = match self.center_width {
            Some(w) => (w - self.line_width(spans)) / 2.0,
            None => 0.0,
        };
        for span in spans {
            let face = self.span_face(span);
            for ch in span.text.chars() {
                let adv = char_advance(face, span.bold, ch) * self.size;
                let (ix, bin) = subpixel(x);
                if let Some(img) = render_glyph(face, ch, span.bold, span.italic, self.size, bin) {
                    for yy in 0..img.h {
                        for xx in 0..img.w {
                            let cov = img.data[yy * img.w + xx];
                            if cov <= 0.0 {
                                continue;
                            }
                            let a = ((cov * span.color.a as f32) + 0.5) as u32;
                            if a == 0 {
                                continue;
                            }
                            let px = (ix + img.left + xx as i32) as f32;
                            let py = gy + (img.top + yy as i32) as f32;
                            let c = RgbaColor::new(span.color.r, span.color.g, span.color.b, a.min(255) as u8);
                            blend_unit_rect(pixmap, self.origin.0 + px, self.origin.1 + py, c);
                        }
                    }
                }
                x += adv;
            }
        }
    }
}
