impl Path {
    /// Apply `x' = a*x + c*y + e`, `y' = b*x + d*y + f` where the shear is
    /// expressed in a y-down coordinate system.
    pub fn transform_affine(&self, a: f32, c: f32, b: f32, d: f32, e: f32, f: f32) -> Path {
        Path {
            contours: self
                .contours
                .iter()
                .map(|cn| {
                    cn.iter()
                        .map(|p| Pt {
                            x: a * p.x + c * p.y + e,
                            y: b * p.x + d * p.y + f,
                        })
                        .collect()
                })
                .collect(),
            current: Vec::new(),
        }
    }
}
