        // value with optional comment
        let mut j = value_start;
        while j < n && chars[j] == ' ' {
            j += 1;
        }
        push_chars(&mut out, &chars, value_start, j, "");
        let mut end = n;
        let mut k = j;
        let mut in_q: Option<char> = None;
        while k < n {
            let ch = chars[k];
            if let Some(q) = in_q {
                if ch == q {
                    in_q = None;
                }
            } else if ch == '"' || ch == '\'' {
                in_q = Some(ch);
            } else if ch == '#' && k > 0 && chars[k - 1] == ' ' {
                end = k;
                break;
            }
            k += 1;
        }
        let mut vend = end;
        while vend > j && chars[vend - 1] == ' ' {
            vend -= 1;
        }
        if vend > j {
            let v: String = chars[j..vend].iter().collect();
            let scope = if v.parse::<f64>().is_ok() {
                "constant.numeric.yaml"
            } else if ["true", "false", "null", "yes", "no", "on", "off", "~", "True", "False", "Null"].contains(&v.as_str()) {
                "constant.language.yaml"
            } else if v.starts_with('&') || v.starts_with('*') {
                "variable.other.anchor.yaml"
            } else if v == "|" || v == ">" || v == "|-" || v == ">-" {
                "keyword.control.flow.block-scalar.yaml"
            } else if v.starts_with('[') || v.starts_with('{') {
                ""
            } else {
                "string.unquoted.yaml"
            };
            out.push(&v, scope);
        }
        push_chars(&mut out, &chars, vend, end, "");
        push_chars(&mut out, &chars, end, n, "comment.line.yaml");
    }
    out.lines
}

fn find_key_colon(chars: &[char], start: usize) -> Option<usize> {
    let n = chars.len();
    let mut k = start;
    let mut in_q: Option<char> = None;
    while k < n {
        let ch = chars[k];
        if let Some(q) = in_q {
            if ch == q {
                in_q = None;
            }
        } else if (ch == '"' || ch == '\'') && k == start {
            in_q = Some(ch);
        } else if ch == ':' && (k + 1 == n || chars[k + 1] == ' ') {
            return if k > start { Some(k) } else { None };
        } else if ch == '#' || ch == '[' || ch == '{' {
            return None;
        }
        k += 1;
    }
    None
}

fn lex_shell(code: &str) -> Vec<Vec<Token>> {
    const KEYWORDS: &[&str] = &["if", "then", "else", "elif", "fi", "for", "while", "do", "done", "case", "esac", "in", "function", "until", "select", "return", "local", "export"];
    const BUILTINS: &[&str] = &["echo", "cd", "printf", "read", "source", "exit", "set", "unset", "shift", "test", "eval", "exec", "alias", "trap", "wait", "kill", "pwd", "true", "false", "declare", "let", "type", "command"];
    let chars: Vec<char> = code.chars().collect();
    let n = chars.len();
    let mut out = Out { lines: vec![Vec::new()] };
    let mut i = 0;
    let mut cmd_pos = true; // next word is a command
    let mut after_for = false;
    while i < n {
        let c = chars[i];
        if c == '\n' {
            out.push("\n", "");
            i += 1;
            cmd_pos = true;
            continue;
        }
        if c == '#' && (i == 0 || chars[i - 1].is_whitespace()) {
            let mut j = i;
            while j < n && chars[j] != '\n' {
                j += 1;
            }
            push_chars(&mut out, &chars, i, j, "comment.line.shell");
            i = j;
            continue;
        }
        if c == '"' || c == '\'' {
            let mut j = i + 1;
            let mut seg = i;
            while j < n && chars[j] != c {
                if c == '"' && chars[j] == '\\' {
                    j += 2;
                    continue;
                }
                if c == '"' && chars[j] == '$' && j + 1 < n && (is_ident_start(chars[j + 1]) || chars[j + 1] == '{') {
                    push_chars(&mut out, &chars, seg, j + 1, "string.quoted.shell");
                    let mut k = j + 1;
                    if chars[k] == '{' {
                        while k < n && chars[k] != '}' {
                            k += 1;
                        }
                        k = (k + 1).min(n);
                    } else {
                        while k < n && is_ident_char(chars[k]) {
                            k += 1;
                        }
                    }
                    push_chars(&mut out, &chars, j + 1, k, "variable.other.readwrite.shell");
                    j = k;
                    seg = k;
                    continue;
                }
                j += 1;
            }
            let j = (j + 1).min(n);
            push_chars(&mut out, &chars, seg, j, "string.quoted.shell");
            i = j;
            cmd_pos = false;
            continue;
        }
        if c == '$' {
            let mut j = i + 1;
            if j < n && (chars[j] == '{' || chars[j] == '(') {
                let close = if chars[j] == '{' { '}' } else { ')' };
                while j < n && chars[j] != close && chars[j] != '\n' {
                    j += 1;
                }
                j = (j + 1).min(n);
            } else {
                while j < n && (is_ident_char(chars[j]) || (j == i + 1 && "@#?$!*".contains(chars[j]))) {
                    j += 1;
                }
            }
            out.push("$", "punctuation.definition.variable.shell");
            push_chars(&mut out, &chars, i + 1, j, "variable.other.readwrite.shell");
            i = j;
            cmd_pos = false;
            continue;
        }
        if c == '[' || c == ']' {
            let mut j = i;
            while j < n && chars[j] == c {
                j += 1;
            }
            push_chars(&mut out, &chars, i, j, "support.function.test.shell");
            i = j;
            if c == '[' {
                cmd_pos = false;
            }
            continue;
        }
        if c == '-' && (i == 0 || chars[i - 1].is_whitespace()) && i + 1 < n && (chars[i + 1].is_alphabetic() || chars[i + 1] == '-') && !cmd_pos {
            let mut j = i + 1;
            while j < n && (is_ident_char(chars[j]) || chars[j] == '-') {
                j += 1;
            }
            push_chars(&mut out, &chars, i, j, "variable.parameter.option.shell");
            i = j;
            continue;
        }
        if is_ident_start(c) || c == '.' || c == '/' {
            let mut j = i;
            while j < n && (is_ident_char(chars[j]) || "./-".contains(chars[j])) {
                j += 1;
            }
            let word: String = chars[i..j].iter().collect();
            if j < n && chars[j] == '=' && cmd_pos && word.chars().all(is_ident_char) {
                out.push(&word, "variable.other.readwrite.assignment.shell");
                out.push("=", "keyword.operator.assignment.shell");
                i = j + 1;
                continue;
            }
            let scope = if KEYWORDS.contains(&word.as_str()) {
                if word == "for" {
                    after_for = true;
                }
                "keyword.control.shell"
            } else if after_for {
                after_for = false;
                ""
            } else if cmd_pos && BUILTINS.contains(&word.as_str()) {
                cmd_pos = false;
                "support.function.builtin.shell"
            } else if cmd_pos {
                cmd_pos = false;
                "variable.function.shell"
            } else {
                ""
            };
            if KEYWORDS.contains(&word.as_str()) && word != "in" {
                cmd_pos = true;
            }
            out.push(&word, scope);
            i = j;
            continue;
        }
        if c == '|' || c == ';' || c == '&' {
            let scope = if c == ';' { "" } else { "keyword.operator.logical.shell" };
            out.push(&c.to_string(), scope);
            cmd_pos = true;
            i += 1;
            continue;
        }
        if c == '=' || c == '>' || c == '<' {
            out.push(&c.to_string(), "keyword.operator.shell");
            i += 1;
            continue;
        }
        out.push(&c.to_string(), "");
        i += 1;
    }
    out.lines
}

fn lex_css(code: &str) -> Vec<Vec<Token>> {
    let chars: Vec<char> = code.chars().collect();
    let n = chars.len();
    let mut out = Out { lines: vec![Vec::new()] };
    let mut i = 0;
    let mut depth = 0;
    let mut in_value = false;
    while i < n {
        let c = chars[i];
        if c == '/' && i + 1 < n && chars[i + 1] == '*' {
            let mut j = i + 2;
            while j + 1 < n && !(chars[j] == '*' && chars[j + 1] == '/') {
                j += 1;
            }
            let j = (j + 2).min(n);
            push_chars(&mut out, &chars, i, j, "comment.block.css");
            i = j;
            continue;
        }
        if c == '"' || c == '\'' {
            let mut j = i + 1;
            while j < n && chars[j] != c && chars[j] != '\n' {
                j += 1;
            }
            let j = (j + 1).min(n);
            push_chars(&mut out, &chars, i, j, "string.quoted.css");
            i = j;
            continue;
        }
        if c == '{' {
            depth += 1;
            in_value = false;
            out.push("{", "");
            i += 1;
            continue;
        }
        if c == '}' {
            depth -= 1;
            in_value = false;
            out.push("}", "");
            i += 1;
            continue;
        }
        if depth == 0 {
            // selectors
            if c == '.' || c == '#' {
                let mut j = i + 1;
                while j < n && (is_ident_char(chars[j]) || chars[j] == '-') {
                    j += 1;
                }
                push_chars(&mut out, &chars, i, j, "entity.other.attribute-name.css");
                i = j;
                continue;
            }
            if c == ':' {
                let mut j = i + 1;
                while j < n && (is_ident_char(chars[j]) || chars[j] == '-' || chars[j] == ':') {
                    j += 1;
                }
                push_chars(&mut out, &chars, i, j, "");
                i = j;
                continue;
            }
            if is_ident_start(c) {
                let mut j = i;
                while j < n && (is_ident_char(chars[j]) || chars[j] == '-') {
                    j += 1;
                }
                push_chars(&mut out, &chars, i, j, "entity.name.tag.css");
                i = j;
                continue;
            }
            out.push(&c.to_string(), "");
            i += 1;
            continue;
        }
        if c == ':' && !in_value {
            in_value = true;
            out.push(":", "");
            i += 1;
            continue;
        }
        if c == ';' {
            in_value = false;
            out.push(";", "");
            i += 1;
            continue;
        }
        if !in_value && (is_ident_start(c) || c == '-') {
            let mut j = i;
            while j < n && (is_ident_char(chars[j]) || chars[j] == '-') {
                j += 1;
            }
            push_chars(&mut out, &chars, i, j, "support.type.property-name.css");
            i = j;
            continue;
        }
        if in_value {
            if c == '#' {
                let mut j = i + 1;
                while j < n && chars[j].is_ascii_hexdigit() {
                    j += 1;
                }
                push_chars(&mut out, &chars, i, j, "constant.other.color.css");
                i = j;
                continue;
            }
            if c.is_ascii_digit() || (c == '.' && i + 1 < n && chars[i + 1].is_ascii_digit()) {
                let mut j = i;
                while j < n && (chars[j].is_ascii_digit() || chars[j] == '.') {
                    j += 1;
                }
                push_chars(&mut out, &chars, i, j, "constant.numeric.css");
                let mut k = j;
                while k < n && (chars[k].is_alphabetic() || chars[k] == '%') {
                    k += 1;
                }
                push_chars(&mut out, &chars, j, k, "keyword.other.unit.css");
                i = k;
                continue;
            }
            if is_ident_start(c) || c == '-' {
                let mut j = i;
                while j < n && (is_ident_char(chars[j]) || chars[j] == '-') {
                    j += 1;
                }
                let scope = if j < n && chars[j] == '(' { "support.function.css" } else { "support.constant.property-value.css" };
                push_chars(&mut out, &chars, i, j, scope);
                i = j;
                continue;
            }
            if c == '%' || c == '-' || c == '+' || c == '*' || c == '/' {
                out.push(&c.to_string(), "keyword.operator.css");
                i += 1;
                continue;
            }
        }
        out.push(&c.to_string(), "");
        i += 1;
    }
    out.lines
}

