fn lex_yaml(code: &str) -> Vec<Vec<Token>> {
    let mut out = Out { lines: vec![Vec::new()] };
    let mut first = true;
    for line in code.split('\n') {
        if !first {
            out.push("\n", "");
        }
        first = false;
        let chars: Vec<char> = line.chars().collect();
        let n = chars.len();
        let mut i = 0;
        while i < n && chars[i].is_whitespace() {
            i += 1;
        }
        push_chars(&mut out, &chars, 0, i, "");
        if i < n && chars[i] == '#' {
            push_chars(&mut out, &chars, i, n, "comment.line.yaml");
            continue;
        }
        if i + 1 < n && chars[i] == '-' && chars[i + 1] == ' ' {
            out.push("-", "");
            i += 1;
        }
        // key
        let rest: String = chars[i..].iter().collect();
        let mut value_start = i;
        if let Some(pos) = find_key_colon(&chars, i) {
            push_chars(&mut out, &chars, i, pos, "entity.name.tag.yaml");
            out.push(":", "");
            value_start = pos + 1;
        }
        let _ = rest;
        // value with optional comment
        let mut j = value_start;
        while j < n && chars[j] == ' ' {
            j += 1;
        }
        push_chars(&mut out, &chars, value_start, j, "");
        let mut end = n;
        let mut k = j;
        let mut in_q: Option<char> = None;
        while k < n {
            let ch = chars[k];
            if let Some(q) = in_q {
                if ch == q {
                    in_q = None;
                }
            } else if ch == '"' || ch == '\'' {
                in_q = Some(ch);
            } else if ch == '#' && k > 0 && chars[k - 1] == ' ' {
                end = k;
                break;
            }
            k += 1;
        }
        let mut vend = end;
        while vend > j && chars[vend - 1] == ' ' {
            vend -= 1;
        }
        if vend > j {
            let v: String = chars[j..vend].iter().collect();
            let scope = if v.parse::<f64>().is_ok() {
                "constant.numeric.yaml"
            } else if ["true", "false", "null", "yes", "no", "on", "off", "~", "True", "False", "Null"].contains(&v.as_str()) {
                "constant.language.yaml"
            } else if v.starts_with('&') || v.starts_with('*') {
                "variable.other.anchor.yaml"
            } else if v == "|" || v == ">" || v == "|-" || v == ">-" {
                "keyword.control.flow.block-scalar.yaml"
            } else if v.starts_with('[') || v.starts_with('{') {
                ""
            } else {
                "string.unquoted.yaml"
            };
            out.push(&v, scope);
        }
        push_chars(&mut out, &chars, vend, end, "");
        push_chars(&mut out, &chars, end, n, "comment.line.yaml");
    }
    out.lines
}

fn find_key_colon(chars: &[char], start: usize) -> Option<usize> {
    let n = chars.len();
    let mut k = start;
    let mut in_q: Option<char> = None;
    while k < n {
        let ch = chars[k];
        if let Some(q) = in_q {
            if ch == q {
                in_q = None;
            }
        } else if (ch == '"' || ch == '\'') && k == start {
            in_q = Some(ch);
        } else if ch == ':' && (k + 1 == n || chars[k + 1] == ' ') {
            return if k > start { Some(k) } else { None };
        } else if ch == '#' || ch == '[' || ch == '{' {
            return None;
        }
        k += 1;
    }
    None
}

